contracts/Bond.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import {IUniswapV3Factory, IUniswapV3Pool, IUniswapV3MintCallback} from "./interfaces/IUniswapV3.sol";
import {PoolMath} from "./libraries/PoolMath.sol";

/// @title Bond — "The Bond"
/// @notice A protocol-owned market maker posted on a token at graduation and locked forever. It holds three
/// Uniswap v3 positions and rebalances them so the pool has a floor it can't be rugged below:
///   - Sherwood     : a full-range LP (baseline liquidity). Principal is NEVER withdrawn; its swap fees are
///                compounded straight back INTO the position on every poke, so the permanent locked liquidity
///                only ever grows — forever. Nothing is collected out to any wallet.
///   - Bounty     : a single-sided WETH range order just BELOW the price (a falling ladder of bids). Buys dips.
///   - Ambush : a single-sided token range order HIGH above the price (~3x–25x). Sells only into strength;
///                the WETH it earns funds the Bounty.
/// A permissionless `poke()` recenters the Bounty (all held WETH) and Ambush (all held tokens) around the
/// current price — which both ratchets the floor up after a pump and recycles caught tokens after a dump.
///
/// Anti-rug by construction: there is NO function that sends WETH or tokens to an arbitrary address. Sherwood
/// principal is never burned; Bounty/Ambush funds only ever become pool positions or sit here awaiting the
/// next poke; Sherwood fees are compounded back into the locked position rather than paid out. NOTHING ever
/// leaves the Bond to any wallet — there is no owner, setter, or drain.
contract Bond is IUniswapV3MintCallback, ReentrancyGuard {
    using SafeERC20 for IERC20;

    uint24 public constant POOL_FEE = 10000;
    int24 public constant SPACING = 200; // 1% tier tick spacing
    uint128 internal constant U128_MAX = type(uint128).max;
    address internal constant DEAD = 0x000000000000000000000000000000000000dEaD;

    // Band geometry (ticks from the current price; all multiples of SPACING). 1 tick ≈ 1.0001x.
    int24 public constant BOUNTY_NEAR = 200; //   ~+0%   : Bounty starts one spacing off spot
    int24 public constant BOUNTY_FAR = 6800; //   ~-49%  : ...down to roughly half price (a wide buy wall)
    int24 public constant AMBUSH_NEAR = 11000; // ~3.0x  : Ambush start ~3x
    int24 public constant AMBUSH_FAR = 32000; //  ~24.5x : ...up to ~25x
    int24 public constant MAX_DEV = 300; //     ~3%    : max spot-vs-TWAP deviation to allow a poke
    // 15s TWAP for the poke guard. On Robinhood Chain (~0.1s blocks, ≤1 oracle obs/active block) the curve
    // seeds the pool with cardinality 200 (~20s of buffer) — the most a single launch tx can afford under the
    // chain's 2**24 (~16.7M) per-tx gas cap — so observe(15) has ~5s of headroom and never reverts "OLD" even
    // under an every-block pump. (Coins can grow the buffer further post-launch via CurvePool.growOracle for a
    // wider margin, but 15s is covered without it.) A short recent window also keeps spot close to the mean, so
    // poke() succeeds during pumps (when recentering matters) while still bounding manipulation to MAX_DEV.
    // Bands are placed relative to spot (never straddling it); the residual within-band spot manipulation is
    // marginal (1% fee tier, bounded to the small recycled balance) — the floor-draining graduation vector is
    // closed in CurvePool.
    uint32 public constant TWAP_WINDOW = 15;
    int24 internal constant TICK_BOUND = 887200; // clamp band ticks to the valid (spacing-snapped) range

    IERC20 public immutable token;
    address public immutable WETH;
    IUniswapV3Pool public immutable pool;
    address public immutable token0;
    address public immutable token1;
    address public immutable platform; // retained for deploy-interface stability; no longer a fee sink
    address public immutable curve; // only the curve may post()
    bool public immutable tokenIsToken0;
    bool public immutable bountyBelow; // Bounty (WETH) sits below price iff WETH is token1

    bool public posted;
    int24 public sherwoodLo;
    int24 public sherwoodHi;
    uint128 public sherwoodL;
    int24 public bountyLo;
    int24 public bountyHi;
    uint128 public bountyL;
    int24 public ambushLo;
    int24 public ambushHi;
    uint128 public ambushL;

    bool private _minting;

    error NotCurve();
    error AlreadyPosted();
    error NotPosted();
    error NoPool();
    error NotPool();
    error Manipulated();

    event Posted(uint128 sherwoodL, uint128 bountyL, uint128 ambushL);
    event Poked(int24 tick, uint128 bountyL, uint128 ambushL, uint256 sherwoodFees0, uint256 sherwoodFees1);

    constructor(address token_, address weth_, address v3Factory_, address platform_, address curve_) {
        require(token_ != address(0) && weth_ != address(0) && platform_ != address(0) && curve_ != address(0), "zero");
        address p = IUniswapV3Factory(v3Factory_).getPool(token_, weth_, POOL_FEE);
        if (p == address(0)) revert NoPool();
        (uint160 sp,,,,,,) = IUniswapV3Pool(p).slot0();
        if (sp == 0) revert NoPool();
        token = IERC20(token_);
        WETH = weth_;
        pool = IUniswapV3Pool(p);
        platform = platform_;
        curve = curve_;
        bool tIs0 = token_ < weth_;
        tokenIsToken0 = tIs0;
        bountyBelow = tIs0; // WETH is token1 -> Bounty (WETH) is the below-price band
        (token0, token1) = tIs0 ? (token_, weth_) : (weth_, token_);
    }

    /// @notice Posted once by the curve at graduation. The Bond must already hold `sherwoodWeth + bountyWeth` WETH
    /// and `sherwoodTokens + ambushTokens` of the token. Mints the three positions.
    function post(uint256 sherwoodWeth, uint256 sherwoodTokens, uint256 bountyWeth, uint256 ambushTokens)
        external
        nonReentrant
    {
        if (msg.sender != curve) revert NotCurve();
        if (posted) revert AlreadyPosted();
        posted = true;

        (uint160 sp, int24 tick,,,,,) = pool.slot0();

        // 1) Sherwood — full-range baseline liquidity (locked; only fees ever leave)
        (uint256 a0, uint256 a1) = tokenIsToken0 ? (sherwoodTokens, sherwoodWeth) : (sherwoodWeth, sherwoodTokens);
        uint128 kL = PoolMath.fullRangeLiquidity(sp, a0, a1);
        sherwoodLo = PoolMath.MIN_TICK;
        sherwoodHi = PoolMath.MAX_TICK;
        sherwoodL = kL;
        _mint(sherwoodLo, sherwoodHi, kL);

        // 2) Bounty (WETH) + 3) Ambush (token) — single-sided range orders. post() is atomic inside graduate()
        // (curve-only, no front-run window) and the oracle may be too fresh for a TWAP, so anchor to the honest
        // just-set spot on both sides (aboveAnchor == belowAnchor == tick) — identical to the original behavior.
        _placeBounty(tick, tick, bountyWeth);
        _placeAmbush(tick, tick, ambushTokens);

        emit Posted(sherwoodL, bountyL, ambushL);
    }

    /// @notice Permissionless keeper. Compounds Sherwood swap fees back into the locked LP, then recenters the Bounty (all held
    /// WETH) and Ambush (all held tokens) around the current price — ratcheting the floor and recycling
    /// caught supply. Guarded by a spot-vs-TWAP deviation check so it can't be poked at a manipulated price.
    function poke() external nonReentrant {
        if (!posted) revert NotPosted();
        (uint160 sp, int24 tick,,,,,) = pool.slot0();
        int24 mean = _requireUnmanipulated(tick);
        // Anchor the recenter walls to the CONSERVATIVE side of {spot, TWAP mean}, not raw spot: above-bands to
        // max(spot,mean), below-bands to min(spot,mean). Within the allowed ±MAX_DEV, an attacker who shoves spot to
        // make a wall richer for themselves (e.g. lift the Bounty bid toward true price to dump into) instead falls
        // back to the honest mean, removing the profitable component; whichever way they push, a band stays strictly
        // single-sided w.r.t. spot (NEAR=200 < MAX_DEV=300 would otherwise let a mean-only center straddle spot).
        int24 aboveAnchor = tick > mean ? tick : mean;
        int24 belowAnchor = tick < mean ? tick : mean;

        // Sherwood: poke the position to realize fees, collect them HERE, and compound them straight back
        // into the locked full-range position. The permanent, never-withdrawable liquidity therefore GROWS
        // with every trade — forever — instead of the fees leaving. Any side left over after the balanced
        // full-range mint (fees are rarely perfectly balanced) falls through to the Bounty/Ambush recenter
        // below, so nothing is ever stranded.
        pool.burn(sherwoodLo, sherwoodHi, 0);
        (uint128 kf0, uint128 kf1) = pool.collect(address(this), sherwoodLo, sherwoodHi, U128_MAX, U128_MAX);
        uint128 addL = PoolMath.fullRangeLiquidityOrZero(sp, kf0, kf1);
        if (addL > 0) {
            sherwoodL += addL;
            _mint(sherwoodLo, sherwoodHi, addL);
        }

        // tear down Bounty + Ambush, pull everything back here
        if (bountyL > 0) {
            pool.burn(bountyLo, bountyHi, bountyL);
            pool.collect(address(this), bountyLo, bountyHi, U128_MAX, U128_MAX);
            bountyL = 0;
        }
        if (ambushL > 0) {
            pool.burn(ambushLo, ambushHi, ambushL);
            pool.collect(address(this), ambushLo, ambushHi, U128_MAX, U128_MAX);
            ambushL = 0;
        }

        // recenter around the current price: all WETH -> Bounty, all tokens -> Ambush
        uint256 wbal = IERC20(WETH).balanceOf(address(this));
        uint256 tbal = token.balanceOf(address(this));
        if (wbal > 0) _placeBounty(aboveAnchor, belowAnchor, wbal);
        if (tbal > 0) _placeAmbush(aboveAnchor, belowAnchor, tbal);
        emit Poked(tick, bountyL, ambushL, kf0, kf1);
    }

    // --------------------------------------------------------------- internals
    function _placeBounty(int24 aboveAnchor, int24 belowAnchor, uint256 wethAmt) internal {
        // Bounty holds WETH, on the "token gets cheaper" side (below price iff WETH is token1). Anchor to the
        // conservative side: an above-band to max(spot,mean), a below-band to min(spot,mean).
        bool above = bountyBelow ? false : true;
        (int24 lo, int24 hi,) = _band(above ? aboveAnchor : belowAnchor, above, BOUNTY_NEAR, BOUNTY_FAR);
        // OrZero: skip (don't revert) if the amount is 0 or too small to make any liquidity — the WETH just
        // stays here for the next poke instead of bricking this one.
        uint128 L = PoolMath.singleSidedLiquidityOrZero(PoolMath.getSqrtRatioAtTick(lo), PoolMath.getSqrtRatioAtTick(hi), wethAmt, above);
        if (L == 0) return;
        bountyLo = lo;
        bountyHi = hi;
        bountyL = L;
        _mint(lo, hi, L);
    }

    function _placeAmbush(int24 aboveAnchor, int24 belowAnchor, uint256 tokenAmt) internal {
        // Ambush hold the token, on the "token gets more expensive" side (opposite of the Bounty).
        bool above = bountyBelow ? true : false;
        (int24 lo, int24 hi,) = _band(above ? aboveAnchor : belowAnchor, above, AMBUSH_NEAR, AMBUSH_FAR);
        uint128 L = PoolMath.singleSidedLiquidityOrZero(PoolMath.getSqrtRatioAtTick(lo), PoolMath.getSqrtRatioAtTick(hi), tokenAmt, above);
        if (L == 0) return;
        ambushLo = lo;
        ambushHi = hi;
        ambushL = L;
        _mint(lo, hi, L);
    }

    /// @dev A single-sided band `near..far` ticks away from the current price, on the ABOVE or BELOW side.
    /// `above` selects the side; token0Side == above (a band above the current tick holds only token0).
    /// Band ticks are clamped to the valid range so an extreme price can never push a bound past ±887200
    /// (which would revert getSqrtRatioAtTick / mint and brick poke).
    function _band(int24 tick, bool above, int24 near, int24 far) internal pure returns (int24 lo, int24 hi, bool isAbove) {
        int24 base = _snapDown(tick);
        if (above) {
            lo = _clamp(base + near);
            hi = _clamp(base + far);
        } else {
            lo = _clamp(base - far);
            hi = _clamp(base - near);
        }
        return (lo, hi, above);
    }

    function _clamp(int24 t) internal pure returns (int24) {
        if (t > TICK_BOUND) return TICK_BOUND;
        if (t < -TICK_BOUND) return -TICK_BOUND;
        return t;
    }

    function _snapDown(int24 t) internal pure returns (int24) {
        int24 r = t % SPACING;
        if (r != 0 && t < 0) return t - r - SPACING; // floor toward -inf
        return t - r;
    }

    function _requireUnmanipulated(int24 spotTick) internal view returns (int24 mean) {
        uint32[] memory ago = new uint32[](2);
        ago[0] = TWAP_WINDOW;
        ago[1] = 0;
        (int56[] memory cum,) = pool.observe(ago);
        mean = PoolMath.meanTick(cum[0], cum[1], TWAP_WINDOW);
        int24 d = spotTick > mean ? spotTick - mean : mean - spotTick;
        if (d > MAX_DEV) revert Manipulated();
    }

    function _mint(int24 lo, int24 hi, uint128 L) internal {
        if (L == 0) return;
        _minting = true;
        pool.mint(address(this), lo, hi, L, "");
        _minting = false;
    }

    function uniswapV3MintCallback(uint256 amount0Owed, uint256 amount1Owed, bytes calldata) external override {
        if (msg.sender != address(pool)) revert NotPool();
        require(_minting, "no mint");
        if (amount0Owed > 0) IERC20(token0).safeTransfer(msg.sender, amount0Owed);
        if (amount1Owed > 0) IERC20(token1).safeTransfer(msg.sender, amount1Owed);
    }

    /// @notice WETH currently standing under the price as the Bounty floor (its principal side).
    function floorWeth() external view returns (uint256) {
        return IERC20(WETH).balanceOf(address(this)); // uncommitted; committed floor lives in the pool position
    }
}

contracts/BondingCurve.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

// ⚠️ NOT FOR DEPLOYMENT — ALTERNATE (x*y=k off-DEX) LAUNCH MODEL, SUPERSEDED BY THE CurvePool/CurvePadFactory
// PATH THAT THE PAD ACTUALLY SHIPS (scripts/deploy.js deploys CurvePadFactory, never CurveLaunchFactory). This
// path has two KNOWN, UNFIXED audit findings that the CurvePool path already designs around:
//   D1 (HIGH): the token is deployed via plain nonce-CREATE (CurveTokenDeployer), so its Uniswap pool address
//     is predictable. An attacker can pre-`initialize` that pool once, making every launch's `initialize`
//     revert and permanently BRICK the pad. Fix before use: deploy the token via CREATE2 with per-launch
//     entropy (as LaunchTokenDeployer/CurvePadFactory do), or make initialize tolerant.
//   D2 (MED): graduation gates on `slot0 == gradSqrtPriceX96` exactly; the pre-init pool has zero liquidity so
//     anyone can shove its price for gas and grief graduation. Fix: tolerance band, or pair the raised WETH at
//     graduation instead of trusting the empty-pool price.
// Do NOT deploy CurveLaunchFactory/BondingCurve until D1+D2 are fixed. Kept for reference/tests only.

import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import {Math} from "@openzeppelin/contracts/utils/math/Math.sol";
import {IUniswapV3Factory, IUniswapV3Pool, IWETH9} from "./interfaces/IUniswapV3.sol";
import {PoolMath} from "./libraries/PoolMath.sol";

interface IBondDeployer {
    function deploy(address token, address weth, address v3Factory, address platform, address curve)
        external
        returns (address);
}

interface IBond {
    function post(uint256 sherwoodWeth, uint256 sherwoodTokens, uint256 bountyWeth, uint256 ambushTokens) external;
}

/// @title BondingCurve
/// @notice A simple constant-product (x*y=k) bonding curve with virtual reserves, like ape.store /
/// pump.fun. Buyers trade ETH<->token on the curve for price discovery; when real ETH raised reaches
/// GRAD_TARGET the curve **graduates**: it seeds a Uniswap v3 pool at the curve's final price with the
/// unsold tokens + all raised ETH, permanently locks the LP, and disables curve trading forever.
///
/// Invariants (proven + brute-forced in sim/curve-sim.mjs):
///   INV-J:   reserveEth <= ceilDiv(K, reserveToken) after every op (buy floors, sell ceils). This is the
///            load-bearing property: it makes round-trip/sequence profit impossible and keeps the curve
///            solvent (reserveEth >= VIRT_ETH always).
///   INV-BAL: address(this).balance == raised() + platformBuffer + devSellReserve. The curve can only ever
///            pay out ETH it actually took in; graduation deposits exactly raised() into the LP.
///   INV-GRAD: graduation happens at most once, only when raised >= GRAD_TARGET, seeds the pool at the
///            curve's EXACT final price (continuous), burns the unsold remainder, and locks the LP.
contract BondingCurve is ReentrancyGuard {
    using SafeERC20 for IERC20;

    uint24 public constant POOL_FEE = 10000;
    // Fees: BUY 1% -> platform (streamed live, minus a 0.1% buffer swept to platform at graduation).
    //       SELL 1% -> the project dev, who can burn-and-collect it. LP swap fees -> platform.
    uint16 public constant BUY_FEE_BPS = 100; // 1% on buys
    uint16 public constant BUY_BUFFER_BPS = 10; // 0.1% of a buy kept in-curve as a buffer, sent to platform at grad
    uint16 public constant SELL_FEE_BPS = 100; // 1% on sells -> project dev
    uint16 public constant CARDINALITY = 200; // TWAP observation slots armed at graduation (for the Bond)
    uint16 public constant SHERWOOD_WETH_BPS = 6000; // 60% of the raise seeds the Sherwood LP; 40% seeds the Bounty floor

    // immutables
    IERC20 public immutable token;
    address public immutable WETH;
    IUniswapV3Factory public immutable v3Factory;
    address public immutable bondDeployer; // deploys the per-launch Bond at graduation
    uint256 public immutable ambushSupply; // tokens (held by this curve) handed to the Bond's Ambush at grad
    address public immutable platform; // buy fee + LP (Sherwood) fee recipient
    address public immutable dev; // project dev — receives sell fees (burn or collect)

    uint256 public immutable VIRT_ETH; // virtual ETH reserve (sets the starting price)
    uint256 public immutable CURVE_SUPPLY; // tokens for sale on the curve (must be funded to this contract)
    uint256 public immutable K; // = VIRT_ETH * CURVE_SUPPLY (constant product)
    uint256 public immutable GRAD_TARGET; // real ETH (net of fees) that triggers graduation
    uint160 public immutable gradSqrtPriceX96; // pool price committed + initialized at launch

    // anti-snipe (first window: cap the net ETH per buy; auto-expires)
    uint64 public immutable startTime;
    uint32 public immutable antiSnipeSecs;
    uint256 public immutable maxBuyWei;

    // state
    uint256 public reserveEth; // virtual + real
    uint256 public reserveToken; // tokens still in the curve
    uint256 public platformBuffer; // accrued 0.1% buy buffer, swept to platform at graduation
    uint256 public devSellReserve; // accrued 1% sell fees, for the project dev to burn or collect
    bool public graduated;
    address public pool;
    address public bond; // the Bond posted at graduation (Sherwood + Bounty + Ambush)

    error AlreadyGraduated();
    error NotGraduated();
    error SnipeCap();
    error Slippage();
    error NothingOut();
    error NotPool();
    error TargetNotReached();
    error NotDev();
    error BadAmount();

    event Buy(address indexed buyer, uint256 ethIn, uint256 fee, uint256 tokensOut, uint256 reserveEth, uint256 reserveToken);
    event Sell(address indexed seller, uint256 tokensIn, uint256 ethOut, uint256 fee, uint256 reserveEth, uint256 reserveToken);
    event Graduated(address indexed pool, uint256 ethToLp, uint256 tokensToLp, uint160 sqrtPriceX96);
    event DevCollect(uint256 amount);
    event DevBurn(uint256 ethSpent, uint256 tokensBurned);

    constructor(
        address token_,
        address weth_,
        address v3Factory_,
        address platform_,
        address dev_,
        uint256 virtEth_,
        uint256 curveSupply_,
        uint256 gradTarget_,
        uint32 antiSnipeSecs_,
        uint256 maxBuyWei_,
        address bondDeployer_,
        uint256 ambushSupply_
    ) {
        require(
            token_ != address(0) && weth_ != address(0) && v3Factory_ != address(0)
                && platform_ != address(0) && dev_ != address(0) && bondDeployer_ != address(0),
            "zero addr"
        );
        require(virtEth_ > 0 && curveSupply_ > 0 && gradTarget_ > 0, "params");
        // graduation LP must be a meaningful fraction of the raise (bounds any rounding edge); the
        // continuous-price seeding already removes the step, this just rejects degenerate configs.
        require(gradTarget_ >= virtEth_, "grad<virt");
        token = IERC20(token_);
        WETH = weth_;
        v3Factory = IUniswapV3Factory(v3Factory_);
        bondDeployer = bondDeployer_;
        ambushSupply = ambushSupply_;
        platform = platform_;
        dev = dev_;
        VIRT_ETH = virtEth_;
        CURVE_SUPPLY = curveSupply_;
        K = virtEth_ * curveSupply_; // reverts on overflow (checked)
        GRAD_TARGET = gradTarget_;
        antiSnipeSecs = antiSnipeSecs_;
        maxBuyWei = maxBuyWei_;
        startTime = uint64(block.timestamp);

        reserveEth = virtEth_;
        reserveToken = curveSupply_;

        // Claim + initialize the Uniswap pool NOW, at the deterministic graduation price (the price when
        // raised == GRAD_TARGET). This closes the pre-initialization DoS: since we own+price the pool from
        // launch, no third party can initialize it off-price during the bonding phase to brick graduation.
        // (Deploy token+curve atomically — as CurveLaunchFactory does — so there's no gap before this runs.)
        uint256 gradRE = virtEth_ + gradTarget_;
        uint256 gradRT = K / gradRE;
        (uint256 ga0, uint256 ga1) = token_ < weth_ ? (gradRT, gradRE) : (gradRE, gradRT);
        uint160 sp = PoolMath.sqrtPriceX96FromAmounts(ga0, ga1);
        gradSqrtPriceX96 = sp;
        address p = IUniswapV3Factory(v3Factory_).getPool(token_, weth_, POOL_FEE);
        if (p == address(0)) p = IUniswapV3Factory(v3Factory_).createPool(token_, weth_, POOL_FEE);
        IUniswapV3Pool(p).initialize(sp);
        pool = p;
    }

    /// @notice Real ETH raised so far (net of fees) = what's held for graduation.
    function raised() public view returns (uint256) {
        return reserveEth - VIRT_ETH;
    }

    /// @notice Current spot price, ETH-wei per 1e18 token (1e18-scaled). Never reverts. For display/UX.
    function spotPriceE18() public view returns (uint256) {
        return Math.mulDiv(reserveEth, 1e18, reserveToken);
    }

    /// @notice Progress toward graduation, in basis points (0..10000).
    function gradProgressBps() external view returns (uint256) {
        uint256 r = raised();
        return r >= GRAD_TARGET ? 10_000 : (r * 10_000) / GRAD_TARGET;
    }

    // --------------------------------------------------------------- buy
    /// @notice Buy tokens with ETH along the curve. 1% buy fee: 0.9% streamed to the platform wallet in
    /// real time, 0.1% held in-curve as a buffer and swept to the platform at graduation.
    function buy(uint256 minTokensOut) external payable nonReentrant returns (uint256 tokensOut) {
        if (graduated) revert AlreadyGraduated();
        uint256 fee = (msg.value * BUY_FEE_BPS) / 10_000;
        uint256 netEth = msg.value - fee;
        if (netEth == 0) revert NothingOut();
        if (block.timestamp < uint256(startTime) + antiSnipeSecs && netEth > maxBuyWei) revert SnipeCap();

        // Cap the graduating buy so `raised()` lands EXACTLY on GRAD_TARGET and refund the excess (keeps
        // graduation at the price the pool was initialized to at launch — price-continuous).
        uint256 refundEth;
        {
            uint256 room = GRAD_TARGET - raised(); // > 0 (not graduated)
            if (netEth > room) {
                uint256 acceptGross = Math.ceilDiv(room * 10_000, 10_000 - BUY_FEE_BPS);
                if (acceptGross > msg.value) acceptGross = msg.value;
                refundEth = msg.value - acceptGross;
                fee = acceptGross - room;
                netEth = room;
            }
        }

        // constant product: new token reserve = K / new eth reserve
        uint256 newReserveEth = reserveEth + netEth;
        // buy rounding is generous by <1 token-wei; safety comes from the sell-side ceilDiv + the
        // fees (invariant: reserveEth <= ceilDiv(K, reserveToken)), NOT from dust staying in the curve.
        uint256 newReserveToken = K / newReserveEth;
        tokensOut = reserveToken - newReserveToken;
        if (tokensOut < minTokensOut) revert Slippage();
        if (tokensOut == 0) revert NothingOut();

        reserveEth = newReserveEth;
        reserveToken = newReserveToken;

        // split the buy fee: 0.1% buffer stays, the rest streams to the platform wallet now
        uint256 buffer = (fee * BUY_BUFFER_BPS) / BUY_FEE_BPS; // 0.1% of the buy (= 10% of the fee)
        platformBuffer += buffer;
        uint256 stream = fee - buffer;

        token.safeTransfer(msg.sender, tokensOut);
        if (stream > 0) _sendEth(platform, stream); // real-time to the platform wallet (a fixed EOA)
        if (refundEth > 0) _sendEth(msg.sender, refundEth);
        emit Buy(msg.sender, msg.value - refundEth, fee, tokensOut, reserveEth, reserveToken);

        if (raised() >= GRAD_TARGET) _graduate();
    }

    // --------------------------------------------------------------- sell
    /// @notice Sell tokens back to the curve for ETH. 1% fee accrues to the project dev (burn or collect).
    function sell(uint256 tokensIn, uint256 minEthOut) external nonReentrant returns (uint256 ethOut) {
        if (graduated) revert AlreadyGraduated();
        require(tokensIn > 0, "zero");
        // never let outstanding tokens on the curve exceed what was funded (solvency depends on it;
        // also rejects sells backed by any supply beyond CURVE_SUPPLY, e.g. a mis-funded/rebasing token)
        require(reserveToken + tokensIn <= CURVE_SUPPLY, "oversell");
        token.safeTransferFrom(msg.sender, address(this), tokensIn);

        uint256 newReserveToken = reserveToken + tokensIn;
        uint256 newReserveEth = Math.ceilDiv(K, newReserveToken); // ceil -> curve keeps dust (pays out less)
        uint256 grossOut = reserveEth - newReserveEth;
        if (grossOut == 0) revert NothingOut(); // sub-threshold sell would burn tokens for 0 ETH
        reserveToken = newReserveToken;
        reserveEth = newReserveEth;

        uint256 fee = (grossOut * SELL_FEE_BPS) / 10_000;
        ethOut = grossOut - fee;
        if (ethOut < minEthOut) revert Slippage();
        devSellReserve += fee; // accrues to the project dev — burn or collect

        _sendEth(msg.sender, ethOut);
        emit Sell(msg.sender, tokensIn, ethOut, fee, reserveEth, reserveToken);
    }

    // --------------------------------------------------------------- project dev: sell fees (burn or collect)
    /// @notice The project dev withdraws accrued sell fees as ETH.
    function devCollect(uint256 amount) external nonReentrant {
        if (msg.sender != dev) revert NotDev();
        if (amount == 0 || amount > devSellReserve) revert BadAmount();
        devSellReserve -= amount;
        _sendEth(dev, amount);
        emit DevCollect(amount);
    }

    /// @notice The project dev spends accrued sell fees to buy tokens on the curve and burn them
    /// (deflationary + adds ETH toward graduation). Pre-graduation only; afterwards use devCollect.
    function devBurn(uint256 amount, uint256 minTokensOut) external nonReentrant returns (uint256 burned) {
        if (msg.sender != dev) revert NotDev();
        if (graduated) revert AlreadyGraduated();
        if (amount == 0 || amount > devSellReserve) revert BadAmount();

        uint256 room = GRAD_TARGET - raised();
        uint256 spend = amount > room ? room : amount; // don't overshoot graduation
        devSellReserve -= spend;

        uint256 newReserveEth = reserveEth + spend;
        uint256 newReserveToken = K / newReserveEth;
        burned = reserveToken - newReserveToken;
        if (burned < minTokensOut) revert Slippage();
        reserveEth = newReserveEth;
        reserveToken = newReserveToken;

        token.safeTransfer(0x000000000000000000000000000000000000dEaD, burned);
        emit DevBurn(spend, burned);

        if (raised() >= GRAD_TARGET) _graduate();
    }

    // --------------------------------------------------------------- graduation
    /// @notice Force-check graduation (also runs automatically at the end of a qualifying buy).
    function graduate() external nonReentrant {
        if (graduated) revert AlreadyGraduated();
        if (raised() < GRAD_TARGET) revert TargetNotReached();
        _graduate();
    }

    function _graduate() internal {
        graduated = true;
        uint256 ethToLp = raised(); // real ETH raised (accrued fees stay claimable, not deposited)
        require(ethToLp > 0, "empty grad");

        // The pool is ours from launch, so it must still be at gradSqrtPriceX96. Requiring this refuses to
        // seed into a pool whose price a griefer moved (they'd need real liquidity + a swap — costly, no
        // profit, defeated by a private mempool); reverting graduation is safe (no theft, ETH exitable).
        address p = pool;
        (uint160 existing,,,,,,) = IUniswapV3Pool(p).slot0();
        require(existing == gradSqrtPriceX96, "pool price moved");
        IUniswapV3Pool(p).increaseObservationCardinalityNext(CARDINALITY); // arm the TWAP for the Bond's poke guard

        // Split the raise: SHERWOOD_WETH_BPS seeds the Sherwood LP, the rest seeds the Bounty floor.
        uint256 sherwoodWeth = (ethToLp * SHERWOOD_WETH_BPS) / 10_000;
        uint256 bountyWeth = ethToLp - sherwoodWeth;

        // Sherwood tokens: pair `sherwoodWeth` at the committed graduation price; burn the unsold curve remainder
        // (NOT the ambush reserve, which is handed to the Bond's Ambush).
        uint256 quote = PoolMath.quoteWethPerToken(gradSqrtPriceX96, address(token) < WETH); // WETH-wei per 1e18 token
        require(quote > 0, "bad price");
        uint256 sherwoodTokens = Math.min(reserveToken, Math.mulDiv(sherwoodWeth, 1e18, quote));
        require(sherwoodTokens > 0, "empty grad");
        uint256 burnTokens = reserveToken - sherwoodTokens;
        if (burnTokens > 0) token.safeTransfer(0x000000000000000000000000000000000000dEaD, burnTokens);

        // Deploy the Bond, fund it (all raised ETH as WETH + Sherwood tokens + the Ambush reserve), and post.
        IWETH9(WETH).deposit{value: ethToLp}();
        address b = IBondDeployer(bondDeployer).deploy(address(token), WETH, address(v3Factory), platform, address(this));
        bond = b;
        IERC20(WETH).safeTransfer(b, ethToLp);
        IERC20(token).safeTransfer(b, sherwoodTokens + ambushSupply);
        IBond(b).post(sherwoodWeth, sherwoodTokens, bountyWeth, ambushSupply);

        // sweep the accrued buy-fee buffer to the platform (the devSellReserve stays for the dev)
        uint256 buf = platformBuffer;
        platformBuffer = 0;
        if (buf > 0) _sendEth(platform, buf);

        // sweep any token/WETH dust left by rounding
        uint256 tokDust = token.balanceOf(address(this));
        if (tokDust > 0) token.safeTransfer(0x000000000000000000000000000000000000dEaD, tokDust);
        uint256 wethDust = IERC20(WETH).balanceOf(address(this));
        if (wethDust > 0) IERC20(WETH).safeTransfer(platform, wethDust);

        emit Graduated(p, ethToLp, sherwoodTokens, gradSqrtPriceX96);
    }

    // --------------------------------------------------------------- helpers
    function _sendEth(address to, uint256 amount) internal {
        (bool ok,) = to.call{value: amount}("");
        require(ok, "eth send");
    }
}

contracts/CurveLaunchFactory.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {Ownable2Step, Ownable} from "@openzeppelin/contracts/access/Ownable2Step.sol";
import {CurveTokenDeployer, BondingCurveDeployer} from "./deployers/CurveDeployers.sol";

/// @title CurveLaunchFactory
/// @notice Launchpad-for-many (bonding-curve model). Each launch mints a fixed 1B supply and funds a single
/// bonding curve with all of it: 75% trades on the curve, 25% is reserved as the Bond's Ambush. When the
/// curve collects GRAD_TARGET it graduates and posts "The Sheriff's Bond" — Sherwood (locked full-range LP) +
/// Bounty (an ETH floor that buys dips) + Ambush (the 25%, sold only into strength). Buy fee 1% -> platform;
/// sell fee 1% -> project dev; Sherwood LP swap fees -> platform. Projects only pick name / ticker / dev.
contract CurveLaunchFactory is Ownable2Step {
    using SafeERC20 for IERC20;

    uint16 public constant AMBUSH_BPS = 2500; // 25% reserved for the Bond's Ambush; 75% trades on the curve

    address public immutable WETH;
    address public immutable v3Factory;
    CurveTokenDeployer public immutable tokenDeployer;
    BondingCurveDeployer public immutable curveDeployer;
    address public immutable bondDeployer; // deploys the per-launch Bond at graduation

    address public platform; // buy fee + Sherwood LP fee recipient

    // ---- fixed, oracle-free terms — identical for every launch ----
    uint256 public constant TOTAL_SUPPLY = 1_000_000_000 ether; // 1B tokens (18 decimals)
    uint256 public constant VIRT_ETH = 0.8 ether;               // start MC = 1.25*VIRT = 1 ETH (~$1.9k)
    uint256 public constant GRAD_TARGET = 4 ether;              // graduate when the curve collects 4 ETH
    uint32 public constant ANTISNIPE_SECS = 300;                // 5-min opening window
    uint256 public constant MAX_BUY_WEI = 0.1 ether;            // per-buy cap during that window

    struct LaunchParams {
        string name;
        string symbol;
        address dev; // project dev: gets the 1% sell fee (burn or collect)
    }

    struct Record {
        address token;
        address curve;
        address dev;
        uint256 at;
    }

    mapping(address => Record) public recordOf;
    address[] public allTokens;

    error BadValue();

    event Launched(address indexed token, address indexed curve, address dev, uint256 supply);
    event PlatformChanged(address platform);

    constructor(
        address weth_,
        address v3Factory_,
        address platform_,
        address owner_,
        address tokenDeployer_,
        address curveDeployer_,
        address bondDeployer_
    ) Ownable(owner_) {
        require(
            weth_ != address(0) && v3Factory_ != address(0) && platform_ != address(0) && tokenDeployer_ != address(0)
                && curveDeployer_ != address(0) && bondDeployer_ != address(0),
            "zero"
        );
        WETH = weth_;
        v3Factory = v3Factory_;
        platform = platform_;
        tokenDeployer = CurveTokenDeployer(tokenDeployer_);
        curveDeployer = BondingCurveDeployer(curveDeployer_);
        bondDeployer = bondDeployer_;
    }

    /// @notice Launch a token on the pad's standard, oracle-free terms: 1B supply, ~$1.9k start MC,
    /// graduation at 4 ETH, 75% curve / 25% Ambush. Projects only pick name / ticker / dev.
    function launch(LaunchParams calldata p) external returns (address token, address curve) {
        if (p.dev == address(0)) revert BadValue();

        uint256 ambushAmt = (TOTAL_SUPPLY * AMBUSH_BPS) / 10_000; // 25% -> Bond Ambush (held by the curve until grad)
        uint256 curveAmt = TOTAL_SUPPLY - ambushAmt; // 75% trades on the curve

        // 1) token minted to this factory
        token = tokenDeployer.deploy(p.name, p.symbol, TOTAL_SUPPLY, address(this));

        // 2) bonding curve — trades `curveAmt`, holds `ambushAmt` for the Bond; posts the Bond at graduation
        curve = curveDeployer.deploy(
            token, WETH, v3Factory, platform, p.dev, VIRT_ETH, curveAmt, GRAD_TARGET, ANTISNIPE_SECS, MAX_BUY_WEI,
            bondDeployer, ambushAmt
        );

        // 3) fund the curve with the whole supply (curveAmt tradeable + ambushAmt reserved for the Bond)
        IERC20(token).safeTransfer(curve, TOTAL_SUPPLY);

        recordOf[token] = Record(token, curve, p.dev, block.timestamp);
        allTokens.push(token);
        emit Launched(token, curve, p.dev, TOTAL_SUPPLY);
        // NOTE: after graduation the Bond exists at BondingCurve.bond(); anyone can call Bond.poke() to
        // recenter the floor (permissionless keeper).
    }

    function setPlatform(address p_) external onlyOwner {
        require(p_ != address(0), "zero");
        platform = p_;
        emit PlatformChanged(p_);
    }

    function tokenCount() external view returns (uint256) {
        return allTokens.length;
    }
}

contracts/CurvePadFactory.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {Ownable2Step, Ownable} from "@openzeppelin/contracts/access/Ownable2Step.sol";
import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import {LaunchToken} from "./LaunchToken.sol";
import {LaunchTokenDeployer, CurvePoolDeployer} from "./deployers/CurveDeployers.sol";
import {IUniswapV3Pool, IUniswapV3SwapCallback, IWETH9} from "./interfaces/IUniswapV3.sol";
import {PoolMath} from "./libraries/PoolMath.sol";

interface ICurvePool {
    function pool() external view returns (address);
    function seed() external;
}

interface IPadRouter {
    function register(
        address token,
        address pool,
        address curve,
        address projectWallet,
        uint16 buyBps,
        uint16 sellBps,
        uint16 walletBps,
        uint16 floorBps,
        uint16 burnBps
    ) external;
}

/// @title CurvePadFactory — DEX-day-one launchpad (the NOXA-style model, plus the Bond)
/// @notice One `launch()` call: deploys a clean anti-snipe token, creates a REAL Uniswap v3 pool, seeds the
/// token as a single-sided "curve" position, enables trading, and (optionally) executes the creator's own
/// **dev buy** in the same transaction — before anyone else can trade — so the dev is never sniped on their
/// own coin. The dev buy is uncapped by supply (bounded only by the curve ceiling + the ETH sent). Token is
/// on Uniswap + DexScreener from block one. Free to launch; the platform
/// funds nothing (the token seeds its own liquidity); the dev buy is optional and paid by the dev.
contract CurvePadFactory is Ownable2Step, ReentrancyGuard, IUniswapV3SwapCallback {
    using SafeERC20 for IERC20;

    uint16 public constant AMBUSH_BPS = 2500; // 25% -> the Bond's Ambush; 75% is the curve
    uint24 public constant POOL_FEE = 10000;
    // The dev's atomic opening buy is uncapped by supply — it's bounded only by the curve itself
    // (it can climb to the graduation ceiling, never past) and by how much ETH the dev sends.

    address public immutable WETH;
    address public immutable v3Factory;
    address public immutable router; // PadRouter — the swap desk + project tax
    LaunchTokenDeployer public immutable tokenDeployer;
    CurvePoolDeployer public immutable curveDeployer;
    address public immutable bondDeployer;
    address public immutable feeConfig; // owner-governed LP/swap split source, handed to every curve

    address public platform;
    bool private _swapping; // guards the swap callback (WETH is only ever transient, mid-launch)
    address private _activePool; // the pool we're mid-swap with (callback authenticity check)

    // ---- fixed terms ----
    uint256 public constant TOTAL_SUPPLY = 1_000_000_000 ether;
    // Curve geometry is set at deploy so we can run a cheap TEST factory (small width -> graduates after a
    // few $ of buys) next to the real PRODUCTION factory, sharing the same audited code + router.
    int24 public immutable START_TICK_MAG; // e.g. 201600 -> ~$4k start FDV; sign set by ordering
    int24 public immutable CURVE_WIDTH; // span to the curve CEILING (buys can climb here, never past)
    int24 public immutable MIN_GRAD_WIDTH; // span to the MINIMUM graduation price (< CURVE_WIDTH); "let it ride" above

    /// @notice A project's self-chosen tax. Both rates are hard-capped at 4% by the router; the platform
    /// always takes 25% of whatever is collected. The three allocation splits are of the PROJECT'S 75% share
    /// and must sum to 100% (10000 bps): to the project wallet, to deepening the Bond floor, and to auto-burn.
    struct TaxParams {
        uint16 buyBps; // ≤ 400
        uint16 sellBps; // ≤ 400
        uint16 walletBps; // project-share split \_
        uint16 floorBps; //                       > sum to 10000
        uint16 burnBps; //                      _/
        address projectWallet; // 0 => the dev
    }

    struct LaunchParams {
        string name;
        string symbol;
        address dev;
        TaxParams tax;
    }

    struct Record {
        address token;
        address curve;
        address dev;
        uint256 at;
    }

    mapping(address => Record) public recordOf;
    address[] public allTokens;

    error BadValue();

    event Launched(address indexed token, address indexed curve, address indexed pool, address dev, uint256 devBought);
    event PlatformChanged(address platform);

    constructor(
        address weth_,
        address v3Factory_,
        address platform_,
        address owner_,
        address router_,
        address tokenDeployer_,
        address curveDeployer_,
        address bondDeployer_,
        address feeConfig_,
        int24 startTickMag_,
        int24 curveWidth_,
        int24 minGradWidth_
    ) Ownable(owner_) {
        require(
            weth_ != address(0) && v3Factory_ != address(0) && platform_ != address(0) && router_ != address(0)
                && tokenDeployer_ != address(0) && curveDeployer_ != address(0) && bondDeployer_ != address(0),
            "zero"
        );
        require(
            startTickMag_ > 0 && curveWidth_ > 0 && startTickMag_ % 200 == 0 && curveWidth_ % 200 == 0
                && minGradWidth_ > 0 && minGradWidth_ % 200 == 0 && minGradWidth_ < curveWidth_
                // derived grad tick magnitude must stay inside the usable full-range bound (spacing-200 → 887200),
                // or seed()/getSqrtRatioAtTick would revert at the FIRST launch instead of failing here at deploy
                && startTickMag_ + curveWidth_ <= 887200,
            "curve"
        );
        WETH = weth_;
        v3Factory = v3Factory_;
        platform = platform_;
        router = router_;
        tokenDeployer = LaunchTokenDeployer(tokenDeployer_);
        curveDeployer = CurvePoolDeployer(curveDeployer_);
        bondDeployer = bondDeployer_;
        feeConfig = feeConfig_; // may be address(0) → curves default to 100% LP fee to the platform
        START_TICK_MAG = startTickMag_;
        CURVE_WIDTH = curveWidth_;
        MIN_GRAD_WIDTH = minGradWidth_;
    }

    receive() external payable {} // for WETH.withdraw refunds during a dev buy

    /// @notice One tx: token + real pool + seeded curve + trading on. Send ETH to also make the dev's first
    /// buy (≤2%) in the same tx, before trading opens to anyone else. DEX + DexScreener day one.
    function launch(LaunchParams calldata p) external payable nonReentrant returns (address token, address curve, address pool) {
        if (p.dev == address(0)) revert BadValue();

        uint256 ambushAmt = (TOTAL_SUPPLY * AMBUSH_BPS) / 10_000;
        uint256 curveAmt = TOTAL_SUPPLY - ambushAmt;

        LaunchToken.GuardConfig memory g = LaunchToken.GuardConfig({
            deadSecs: 2,
            phase1Secs: 60,
            antiSnipeSecs: 300,
            maxTxBps1: 50,
            maxWalletBps1: 100,
            maxTxBps2: 100,
            maxWalletBps2: 200,
            cooldownSecs: 2
        });
        // CREATE2 salt with per-launch entropy (incl. block.number) so the token — and thus its Uniswap pool
        // address — can't be predicted from the deployer's nonce. An attacker who precreates+initializes the
        // pool to brick a launch would have to win the race for THIS exact block; a retry lands a fresh
        // address, so the DoS can't be made permanent.
        bytes32 salt = keccak256(
            abi.encodePacked(address(this), p.dev, p.name, p.symbol, block.number, block.timestamp, allTokens.length)
        );
        token = tokenDeployer.deploy(p.name, p.symbol, TOTAL_SUPPLY, address(this), g, salt);

        int24 startTick = token < WETH ? -START_TICK_MAG : START_TICK_MAG;
        curve = curveDeployer.deploy(
            token, WETH, v3Factory, platform, p.dev, bondDeployer, feeConfig, curveAmt, ambushAmt, startTick, CURVE_WIDTH, MIN_GRAD_WIDTH
        );
        pool = ICurvePool(curve).pool();

        IERC20(token).safeTransfer(curve, TOTAL_SUPPLY);
        LaunchToken(token).setCurve(curve); // lets the curve exempt the Bond it posts at graduation
        LaunchToken(token).enableTrading(pool, curve, uint64(block.timestamp));
        LaunchToken(token).exemptAddress(router); // router receives tokens on burnDev/flushBurn — never a sniper
        ICurvePool(curve).seed();

        // register the project's tax with the swap desk (router enforces the 4% caps + 100% allocation)
        address projWallet = p.tax.projectWallet == address(0) ? p.dev : p.tax.projectWallet;
        IPadRouter(router).register(
            token, pool, curve, projWallet, p.tax.buyBps, p.tax.sellBps, p.tax.walletBps, p.tax.floorBps, p.tax.burnBps
        );

        // optional dev buy (uncapped by supply), atomic and ahead of the field
        uint256 devBought;
        if (msg.value > 0) devBought = _devBuy(token, pool, startTick, p.dev);

        recordOf[token] = Record(token, curve, p.dev, block.timestamp);
        allTokens.push(token);
        emit Launched(token, curve, pool, p.dev, devBought);
    }

    function _devBuy(address token, address pool, int24 startTick, address dev) internal returns (uint256 bought) {
        bool tokenIsToken0 = token < WETH;
        bool zeroForOne = !tokenIsToken0; // buying the token: WETH-in. WETH is token0 iff !tokenIsToken0.
        // no supply cap on the dev buy: let it climb the whole curve up to the graduation ceiling
        // (buys can never go past it). Any ETH beyond what fills the curve is refunded.
        int24 capTick = tokenIsToken0 ? startTick + CURVE_WIDTH : startTick - CURVE_WIDTH;
        uint160 sqrtLimit = PoolMath.getSqrtRatioAtTick(capTick);

        IWETH9(WETH).deposit{value: msg.value}();
        _swapping = true;
        _activePool = pool;
        IUniswapV3Pool(pool).swap(address(this), zeroForOne, int256(msg.value), sqrtLimit, "");
        _activePool = address(0);
        _swapping = false;

        // deliver bought tokens to the dev; refund any unused ETH (no supply cap on the dev buy)
        bought = IERC20(token).balanceOf(address(this));
        if (bought > 0) IERC20(token).safeTransfer(dev, bought);
        uint256 leftWeth = IERC20(WETH).balanceOf(address(this));
        if (leftWeth > 0) {
            IWETH9(WETH).withdraw(leftWeth);
            (bool ok,) = dev.call{value: leftWeth}("");
            require(ok, "refund");
        }
    }

    function uniswapV3SwapCallback(int256 amount0Delta, int256 amount1Delta, bytes calldata) external override {
        require(_swapping && msg.sender == _activePool, "no swap");
        uint256 owed = amount0Delta > 0 ? uint256(amount0Delta) : uint256(amount1Delta);
        IERC20(WETH).safeTransfer(msg.sender, owed); // msg.sender is the pool mid-swap
    }

    function setPlatform(address p_) external onlyOwner {
        require(p_ != address(0), "zero");
        platform = p_;
        emit PlatformChanged(p_);
    }

    /// @notice Owner-only pass-through so the platform can seed a coin's buy-side sniper blocklist during its
    /// anti-snipe window (the token only accepts seedBlocklist from its factory). It is add-only and the token
    /// auto-freezes it when the window ends, so it can never be used to block a normal holder's sell.
    function seedBlocklist(address token, address[] calldata bots) external onlyOwner {
        LaunchToken(token).seedBlocklist(bots);
    }

    function tokenCount() external view returns (uint256) {
        return allTokens.length;
    }
}

contracts/CurvePool.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import {Math} from "@openzeppelin/contracts/utils/math/Math.sol";
import {IUniswapV3Factory, IUniswapV3Pool, IUniswapV3MintCallback, IUniswapV3SwapCallback} from "./interfaces/IUniswapV3.sol";
import {PoolMath} from "./libraries/PoolMath.sol";

interface ICurveBondDeployer {
    function deploy(address token, address weth, address v3Factory, address platform, address curve)
        external
        returns (address);
}

interface ICurveBond {
    function post(uint256 sherwoodWeth, uint256 sherwoodTokens, uint256 bountyWeth, uint256 ambushTokens) external;
}

interface IFeeConfig {
    function lpCreatorBps() external view returns (uint16);
}

interface ILaunchTokenGuard {
    function exemptAddress(address a) external;
}

/// @title CurvePool — a bonding curve that IS a real Uniswap v3 pool (DEX + DexScreener from block one)
/// @notice Instead of a math curve holding ETH off-DEX, the launch seeds the token as a single-sided
/// concentrated v3 position spanning [start, grad] price. That position behaves like a bonding curve — buyers
/// swap WETH in and walk the price up the range — but it's a genuine Uniswap pool, so DexScreener indexes and
/// charts it the moment it's created. When price reaches the graduation end (the curve is bought out), anyone
/// calls `graduate()`: it collects the raised WETH + any unsold token and posts the Bond (Sherwood + Bounty +
/// Ambush) into the SAME pool. No ETH from the platform — the token seeds its own liquidity; buyers bring ETH.
contract CurvePool is IUniswapV3MintCallback, IUniswapV3SwapCallback, ReentrancyGuard {
    using SafeERC20 for IERC20;

    uint24 public constant POOL_FEE = 10000;
    int24 public constant SPACING = 200;
    uint128 internal constant U128_MAX = type(uint128).max;
    address internal constant DEAD = 0x000000000000000000000000000000000000dEaD;

    IERC20 public immutable token;
    address public immutable WETH;
    IUniswapV3Factory public immutable v3Factory;
    IUniswapV3Pool public immutable pool;
    address public immutable token0;
    address public immutable token1;
    address public immutable platform; // LP-fee + graduation sweep recipient (platform's share)
    address public immutable dev; // project dev — the "creator" fee recipient
    address public immutable bondDeployer;
    address public immutable feeConfig; // owner-governed LP-split source (0 => 100% to platform)
    bool public immutable tokenIsToken0;

    uint256 public immutable curveSupply; // seeded as the single-sided curve
    uint256 public immutable ambushSupply; // paired into the Bond + rolled with any unsold curve tokens
    int24 public immutable startTick; // price at launch (curve bottom)
    int24 public immutable gradTick; // the curve's CEILING — the ONLY graduation point; buys climb to here, never past it
    int24 public immutable minGradTick; // vestigial geometry marker (kept for reporting); graduation is ceiling-only

    uint16 public constant SHERWOOD_WETH_BPS = 6000; // 60% of the raise -> Sherwood LP, 40% -> Bounty floor
    // Graduation reward paid to BOTH the creator and the platform at graduation, in WETH. Capped at raise/4 each
    // (below) so the Bond floor always keeps >=50% of the raise. Graduation only ever happens at the full ceiling
    // (~4.2 ETH raised), so each side takes 0.5 and the floor keeps the rest (>=~3.2 ETH).
    uint256 public constant GRAD_REWARD = 0.5 ether;
    int24 public constant GRAD_MAX_DEV = 50; // graduation can't post above the ceiling by more than this (anti-manipulation)

    bool public seeded;
    bool public graduated;
    uint64 public seedTime; // when the curve was seeded
    address public bond;
    int24 public curveLo;
    int24 public curveHi;
    uint128 public curveL;
    int24 public gradTarget; // vestigial; fixed to gradTick at seed. Graduation is ceiling-only (see ready()).

    bool private _minting;
    bool private _swapping;

    error NotSeeded();
    error AlreadySeeded();
    error AlreadyGraduated();
    error NotReady();
    error NotPool();
    error BadPoolInit();

    event Seeded(int24 curveLo, int24 curveHi, uint128 liquidity);
    event Graduated(address indexed bond, uint256 raisedWeth, uint256 leftoverToken);
    event FeesCollected(address indexed by, uint256 wethFees, uint256 tokenFees, uint16 creatorBps);

    /// @param curveWidth_ tick span from start to the curve CEILING (a positive multiple of SPACING). The ceiling
    /// is the ONLY graduation point — a coin graduates only when buys carry price all the way to it (~4.2 ETH).
    /// @param minGradWidth_ vestigial geometry input (< curveWidth_); it only sets the informational minGradTick
    /// marker and no longer gates graduation.
    constructor(
        address token_,
        address weth_,
        address v3Factory_,
        address platform_,
        address dev_,
        address bondDeployer_,
        address feeConfig_,
        uint256 curveSupply_,
        uint256 ambushSupply_,
        int24 startTick_,
        int24 curveWidth_,
        int24 minGradWidth_
    ) {
        require(
            token_ != address(0) && weth_ != address(0) && v3Factory_ != address(0) && platform_ != address(0)
                && dev_ != address(0) && bondDeployer_ != address(0),
            "zero"
        );
        require(
            curveSupply_ > 0 && ambushSupply_ > 0 && curveWidth_ > 0 && curveWidth_ % SPACING == 0
                && startTick_ % SPACING == 0 && minGradWidth_ > 0 && minGradWidth_ % SPACING == 0
                && minGradWidth_ < curveWidth_,
            "params"
        );
        token = IERC20(token_);
        WETH = weth_;
        v3Factory = IUniswapV3Factory(v3Factory_);
        platform = platform_;
        dev = dev_;
        bondDeployer = bondDeployer_;
        feeConfig = feeConfig_; // may be address(0): then collectFees sends 100% to the platform
        curveSupply = curveSupply_;
        ambushSupply = ambushSupply_;
        startTick = startTick_;

        bool tIs0 = token_ < weth_;
        tokenIsToken0 = tIs0;
        (token0, token1) = tIs0 ? (token_, weth_) : (weth_, token_);
        // The curve holds only the TOKEN. token0 => the token is on the ABOVE-price side (price rises with
        // tick); token1 => the token is on the BELOW-price side (price rises as tick falls).
        gradTick = tIs0 ? startTick_ + curveWidth_ : startTick_ - curveWidth_;
        minGradTick = tIs0 ? startTick_ + minGradWidth_ : startTick_ - minGradWidth_;
        // Graduation target = the FULL ceiling (~4.2 ETH raised). The coin does NOT graduate until it rides all
        // the way to the ceiling, and only then does the creator earn their 0.5 WETH reward. There is no early
        // graduation and no creator-settable target: gradTarget is fixed here at the ceiling (there is no
        // setGradTarget), so ready() flips true only at the ceiling tick. See graduate().
        gradTarget = gradTick;

        // Claim + initialize the pool at the start price (DEX + DexScreener live from here).
        address p = IUniswapV3Factory(v3Factory_).getPool(token_, weth_, POOL_FEE);
        if (p == address(0)) p = IUniswapV3Factory(v3Factory_).createPool(token_, weth_, POOL_FEE);
        uint160 wantSqrt = PoolMath.getSqrtRatioAtTick(startTick_);
        // Guard the initialize: a same-block front-runner could pre-create AND pre-initialize the
        // (token, WETH, 10000) pool, which would make an unconditional initialize() revert and grief the
        // launch. If it is already initialized we accept it ONLY when it sits at our exact start price;
        // any other price is a hostile init and we revert loudly rather than launch onto a wrong curve.
        (uint160 existingSqrt,,,,,,) = IUniswapV3Pool(p).slot0();
        if (existingSqrt == 0) {
            IUniswapV3Pool(p).initialize(wantSqrt);
        } else if (existingSqrt != wantSqrt) {
            revert BadPoolInit();
        }
        pool = IUniswapV3Pool(p);
    }

    /// @notice Seed the curve — mint the single-sided token position. Call once, after this contract has been
    /// funded with `curveSupply + ambushSupply` tokens. Permissionless (idempotent-guarded).
    function seed() external nonReentrant {
        if (seeded) revert AlreadySeeded();
        seeded = true;
        seedTime = uint64(block.timestamp); // record when the curve was seeded (informational)
        // Curve range: token0 => [start, grad] above; token1 => [grad, start] below.
        (int24 lo, int24 hi) = tokenIsToken0 ? (startTick, gradTick) : (gradTick, startTick);
        curveLo = lo;
        curveHi = hi;
        uint128 L =
            PoolMath.singleSidedLiquidity(PoolMath.getSqrtRatioAtTick(lo), PoolMath.getSqrtRatioAtTick(hi), curveSupply, tokenIsToken0);
        curveL = L;
        _mint(lo, hi, L);
        // Arm the TWAP oracle for the Bond's poke() guard. Robinhood Chain runs ~0.1s blocks and stores ≤1
        // observation per active block, so the ring buffer must hold enough slots to span the Bond's TWAP
        // window. 200 slots cover ~20s of continuous every-block trading (> the Bond's 15s window). We cannot
        // ask for more here: Robinhood Chain caps a single tx at 2**24 (~16.7M) gas, and pre-initializing the
        // observation slots is ~20k gas each, so a bigger bump would push launch() over the per-tx cap. Coins
        // that want a wider TWAP margin ramp the buffer up post-launch via growOracle() (many cheap txs).
        pool.increaseObservationCardinalityNext(200);
        emit Seeded(lo, hi, L);
    }

    /// @notice Permissionless: grow the pool's TWAP observation buffer toward `target`. Split across as many
    /// calls as needed so each stays under Robinhood Chain's per-tx gas cap. Only ever increases the buffer
    /// (Uniswap ignores a target ≤ the current one), so it can't shrink or grieve the oracle.
    function growOracle(uint16 target) external {
        pool.increaseObservationCardinalityNext(target);
    }

    /// @notice The pool price at the curve's CEILING. Buyers/routers cap the buy swap here so price can climb
    /// the whole curve (up to the ceiling) but never run past it into empty space.
    function gradSqrtPriceX96() external view returns (uint160) {
        return PoolMath.getSqrtRatioAtTick(gradTick);
    }

    /// @notice Sweep the curve position's accrued Uniswap swap fees (the 1% fee tier) and split them between
    /// the creator and the platform per the owner-governed FeeConfig — the NOXA model, made configurable: the
    /// house keeps the fee on EVERY trade, STREAMED LIVE, instead of only at graduation. It doesn't matter where
    /// a trade executes (pad UI, DexScreener, an aggregator, a raw swap) — every swap hits this one pool and pays
    /// this single-sided position the fee, so this captures 100% of volume.
    ///
    /// Only the FEES move: the curve principal (the accumulating raise that becomes the Bond floor at
    /// graduation) is left fully intact, because Uniswap accounts swap fees separately from position liquidity.
    /// `burn(0)` realizes the accrued fees into the position's `tokensOwed` WITHOUT removing any liquidity;
    /// `collect` pulls them here and we forward the split. Permissionless (a keeper can poke it); the only
    /// recipients are the immutable `dev` (creator) and `platform`, so an untrusted caller can never redirect
    /// the funds — they only pay gas to flush them. Buys pay the fee in WETH, sells in the token → both may move.
    function collectFees() external nonReentrant returns (uint256 wethFees, uint256 tokenFees) {
        if (!seeded) revert NotSeeded();
        if (graduated) revert AlreadyGraduated(); // post-grad the position is burned; fees already swept
        pool.burn(curveLo, curveHi, 0); // poke: moves accrued fees into tokensOwed, principal untouched
        (uint256 c0, uint256 c1) = pool.collect(address(this), curveLo, curveHi, U128_MAX, U128_MAX);
        (wethFees, tokenFees) = tokenIsToken0 ? (c1, c0) : (c0, c1);
        uint16 cbps = _lpCreatorBps();
        _splitFee(IERC20(WETH), wethFees, cbps);
        _splitFee(token, tokenFees, cbps);
        emit FeesCollected(msg.sender, wethFees, tokenFees, cbps);
    }

    /// @dev Pay `amount` of `asset` out as `creatorBps` to the creator (dev) and the remainder to the platform.
    function _splitFee(IERC20 asset, uint256 amount, uint16 creatorBps) internal {
        if (amount == 0) return;
        uint256 toCreator = (amount * creatorBps) / 10_000;
        if (toCreator > 0) asset.safeTransfer(dev, toCreator);
        uint256 toPlatform = amount - toCreator;
        if (toPlatform > 0) asset.safeTransfer(platform, toPlatform);
    }

    /// @dev The creator's LP-fee share (bps) from the owner-governed config, clamped to the 50% hard cap. A
    /// zero/unset/misbehaving config means 0 → 100% to the platform (never reverts a collection).
    function _lpCreatorBps() internal view returns (uint16) {
        address fc = feeConfig;
        if (fc == address(0)) return 0;
        try IFeeConfig(fc).lpCreatorBps() returns (uint16 b) {
            return b > 5000 ? 5000 : b;
        } catch {
            return 0;
        }
    }

    /// @notice Progress: is the coin graduatable? The ONLY way to graduate is reaching the full ceiling
    /// (~4.2 ETH raised / the locked graduation mcap). There is no early graduation and no timeout — a coin that
    /// never reaches the ceiling simply keeps trading on the curve (sellers can always exit), it never posts a
    /// thin Bond. Permissionless: once price reaches the ceiling, anyone may call graduate().
    function ready() public view returns (bool) {
        if (!seeded || graduated) return false;
        (, int24 tick,,,,,) = pool.slot0();
        return tokenIsToken0 ? tick >= gradTick : tick <= gradTick;
    }

    /// @notice Graduate — collect the raised WETH + unsold token from the curve and post the Bond. Permissionless.
    function graduate() external nonReentrant {
        if (!seeded) revert NotSeeded();
        if (graduated) revert AlreadyGraduated();
        if (!ready()) revert NotReady();

        // Anti-manipulation: the Bond is posted around the CURRENT price, so that price must be honest. Inside
        // the curve range [startTick, gradTick] it always is — to move spot UP a buyer must consume curve
        // liquidity, i.e. pay real WETH that JOINS the raise/floor, so a "high" spot is one the attacker funded
        // and the floor sits below it: nothing can be drained. The ONLY unbacked zone is ABOVE the ceiling
        // (no liquidity past gradTick, so spot is free to shove there), so we simply refuse to graduate above
        // the ceiling. That closes the floor-drain vector; graduation only ever fires AT the ceiling anyway.
        (uint160 sp, int24 tickNow,,,,,) = pool.slot0();
        bool aboveCeil = tokenIsToken0 ? tickNow > gradTick + GRAD_MAX_DEV : tickNow < gradTick - GRAD_MAX_DEV;
        if (aboveCeil) {
            // Anti-grief: anyone can shove spot into the empty zone ABOVE the ceiling for ~0 cost (no liquidity
            // past gradTick), which used to make graduate() revert and let an attacker block graduation every
            // block. Instead of reverting, nudge spot back down to the honest ceiling using the curve's OWN
            // still-live liquidity BEFORE we burn it, so the Bond posts around a real, backed price (no drain).
            // Selling the token drives price toward the ceiling; the swap traverses the empty zone consuming ~0
            // and stops exactly at the ceiling limit (the curve position, which ends at gradTick, is untouched).
            uint160 ceilSqrt = PoolMath.getSqrtRatioAtTick(gradTick);
            _swapping = true;
            // Size the nudge to our whole token balance (the ambush reserve). The ceiling price limit stops the
            // swap EXACTLY at the ceiling, so in the honest empty-zone case ~0 is consumed; if an attacker planted
            // real liquidity between spot and the ceiling to defeat a tiny nudge, this powers straight through it
            // (selling tokens above the ceiling only nets extra WETH) until price lands on the ceiling. It can
            // never cross into the curve — the limit is the ceiling — so the raise stays intact.
            pool.swap(address(this), tokenIsToken0, int256(token.balanceOf(address(this))), ceilSqrt, "");
            _swapping = false;
            (sp, tickNow,,,,,) = pool.slot0();
            // must now sit at/below the ceiling; if the nudge somehow didn't land, refuse rather than post high
            bool stillAbove = tokenIsToken0 ? tickNow > gradTick + GRAD_MAX_DEV : tickNow < gradTick - GRAD_MAX_DEV;
            if (stillAbove) revert NotReady();
        }
        graduated = true;

        // Sweep + split any LP fees pending since the last collectFees() FIRST, through the SAME creator/platform
        // split — so the final pre-graduation fee batch honors the fee config instead of silently folding into the
        // raise (and thus the floor). burn(0) realizes only fees into tokensOwed; principal stays in the position.
        {
            pool.burn(curveLo, curveHi, 0);
            (uint256 g0, uint256 g1) = pool.collect(address(this), curveLo, curveHi, U128_MAX, U128_MAX);
            (uint256 wFee, uint256 tFee) = tokenIsToken0 ? (g1, g0) : (g0, g1);
            uint16 cbps = _lpCreatorBps();
            _splitFee(IERC20(WETH), wFee, cbps);
            _splitFee(token, tFee, cbps);
            emit FeesCollected(msg.sender, wFee, tFee, cbps);
        }

        // pull the whole curve position back here (raised WETH + the still-unsold curve tokens) — principal only
        pool.burn(curveLo, curveHi, curveL);
        (uint256 c0, uint256 c1) = pool.collect(address(this), curveLo, curveHi, U128_MAX, U128_MAX);
        (uint256 raisedWeth, uint256 leftToken) = tokenIsToken0 ? (c1, c0) : (c0, c1);
        require(raisedWeth > 0, "empty");

        // Graduation reward: a FIXED 0.5 WETH each to creator + platform (a launch incentive on top of the ongoing
        // fees). Graduation only ever happens at the full ceiling (~4.2 ETH — see ready()), so the creator always
        // earns their 0.5. Capped at raise/4 apiece so the two payouts can never exceed half the raise (the Bond
        // floor always keeps >=50%). Reentrancy-safe (nonReentrant + no callback); dev + platform non-zero.
        uint256 reward = Math.min(GRAD_REWARD, raisedWeth / 4);
        if (reward > 0) {
            raisedWeth -= 2 * reward;
            IERC20(WETH).safeTransfer(dev, reward);      // creator
            IERC20(WETH).safeTransfer(platform, reward); // platform
        }

        // Post the Bond around the CURRENT price. The Sherwood LP needs tokens; pair them from the Ambush
        // reserve PLUS any still-unsold curve tokens (rolled in here rather than burned), and the remainder
        // becomes the Ambush sell-wall whose earnings deepen the floor. Graduating later => bigger raise =>
        // thicker floor AND fewer unsold tokens => a lighter sell-wall.
        uint256 sherwoodWeth = (raisedWeth * SHERWOOD_WETH_BPS) / 10_000;
        uint256 bountyWeth = raisedWeth - sherwoodWeth;
        // The whole token balance goes to the Bond: the ambush reserve + the unsold curve tokens just
        // collected + any rounding dust the seed mint left behind. Using the actual balance (rather than
        // ambushSupply + leftToken) guarantees nothing is stranded in the curve. A stray token donation would
        // only inflate the harmless Ambush wall — it can't be extracted.
        uint256 tokenPool = token.balanceOf(address(this));
        uint256 quote = PoolMath.quoteWethPerToken(sp, tokenIsToken0);
        require(quote > 0, "price"); // fail fast rather than divide-by-zero at an extreme (mis-configured) price
        uint256 sherwoodTokens = Math.min(tokenPool, Math.mulDiv(sherwoodWeth, 1e18, quote));
        // Sherwood needs BOTH sides; a 0 token amount would make Bond.post's fullRangeLiquidity revert "bad
        // liquidity" and brick graduate() (raise stranded in the curve). Unreachable with the pad's large-supply
        // low-price geometry (quote << 1e18 → sherwoodTokens == tokenPool), but assert it with a named error so a
        // misconfigured price/supply fails loudly here rather than deep in the math library.
        require(sherwoodTokens > 0, "sherwood");
        uint256 ambushForBond = tokenPool - sherwoodTokens;

        address b = ICurveBondDeployer(bondDeployer).deploy(address(token), WETH, address(v3Factory), platform, address(this));
        bond = b;
        // Exempt the Bond from the token's anti-snipe guard. Bond.poke()'s pool.collect() moves the Ambush
        // reserve from the pool back to the Bond, which reads as a "buy" (from == pool); without this exemption a
        // coin that graduates INSIDE the anti-snipe window would trip maxTx/maxWallet and brick poke() (and cap
        // buys from the fresh Bond) until the window expires. try/catch so a token that doesn't expose the hook
        // (e.g. a future variant) can never brick graduation — the exemption is best-effort hardening.
        try ILaunchTokenGuard(address(token)).exemptAddress(b) {} catch {}
        IERC20(WETH).safeTransfer(b, raisedWeth);
        IERC20(token).safeTransfer(b, tokenPool); // = sherwoodTokens + ambushForBond
        ICurveBond(b).post(sherwoodWeth, sherwoodTokens, bountyWeth, ambushForBond);

        // sweep any WETH dust
        uint256 wethDust = IERC20(WETH).balanceOf(address(this));
        if (wethDust > 0) IERC20(WETH).safeTransfer(platform, wethDust);

        emit Graduated(b, raisedWeth, leftToken);
    }

    function _mint(int24 lo, int24 hi, uint128 L) internal {
        _minting = true;
        pool.mint(address(this), lo, hi, L, "");
        _minting = false;
    }

    function uniswapV3MintCallback(uint256 amount0Owed, uint256 amount1Owed, bytes calldata) external override {
        if (msg.sender != address(pool)) revert NotPool();
        require(_minting, "no mint");
        if (amount0Owed > 0) IERC20(token0).safeTransfer(msg.sender, amount0Owed);
        if (amount1Owed > 0) IERC20(token1).safeTransfer(msg.sender, amount1Owed);
    }

    /// @dev Only ever invoked by the one-off graduate() nudge that pushes a griefed above-ceiling spot back to
    /// the ceiling. Guarded by `_swapping` (set only inside graduate()) and the pool identity, so no external
    /// caller can drain the curve through it. Pays whatever the pool is owed from this contract's balance.
    function uniswapV3SwapCallback(int256 amount0Delta, int256 amount1Delta, bytes calldata) external override {
        if (msg.sender != address(pool)) revert NotPool();
        require(_swapping, "no swap");
        if (amount0Delta > 0) IERC20(token0).safeTransfer(msg.sender, uint256(amount0Delta));
        if (amount1Delta > 0) IERC20(token1).safeTransfer(msg.sender, uint256(amount1Delta));
    }
}

