// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import {ERC20} from "@openzeppelin/contracts/token/ERC20/ERC20.sol";

/// @notice A plain, fixed-supply, hookless ERC20 for curve launches. No mint, no tax, no blacklist,
/// no owner — the whole supply is minted once to the launchpad, which splits it (10% vault / 90% curve).
/// Anti-snipe lives on the bonding curve (per-buy cap), not on the token, so this stays fully composable.
contract CurveToken is ERC20 {
    constructor(string memory name_, string memory symbol_, uint256 supply_, address recipient_)
        ERC20(name_, symbol_)
    {
        _mint(recipient_, supply_);
    }
}

contracts/deployers/CurveDeployers.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import {CurveToken} from "../CurveToken.sol";
import {BondingCurve} from "../BondingCurve.sol";
import {Bond} from "../Bond.sol";
import {CurvePool} from "../CurvePool.sol";
import {LaunchToken} from "../LaunchToken.sol";
import {OtcVault} from "../OtcVault.sol";

/// @notice Thin deployers so the big contracts' creation bytecode isn't inlined into CurveLaunchFactory
/// (24KB contract-size limit). Each is deployed once and its address handed to the factory.

contract CurveTokenDeployer {
    function deploy(string calldata name, string calldata symbol, uint256 supply, address recipient)
        external
        returns (address)
    {
        return address(new CurveToken(name, symbol, supply, recipient));
    }
}

contract BondingCurveDeployer {
    function deploy(
        address token,
        address weth,
        address v3Factory,
        address platform,
        address dev,
        uint256 virtEth,
        uint256 curveSupply,
        uint256 gradTarget,
        uint32 antiSnipeSecs,
        uint256 maxBuyWei,
        address bondDeployer,
        uint256 ambushSupply
    ) external returns (address) {
        return address(
            new BondingCurve(
                token, weth, v3Factory, platform, dev, virtEth, curveSupply, gradTarget, antiSnipeSecs, maxBuyWei,
                bondDeployer, ambushSupply
            )
        );
    }
}

contract BondDeployer {
    function deploy(address token, address weth, address v3Factory, address platform, address curve)
        external
        returns (address)
    {
        return address(new Bond(token, weth, v3Factory, platform, curve));
    }
}

contract LaunchTokenDeployer {
    /// @dev CREATE2 with a caller-supplied salt so the token (and therefore its Uniswap pool) address is not
    /// a predictable function of this deployer's nonce. That closes a launch-DoS where an attacker precreates
    /// AND initializes the token's WETH pool at the next predictable address, making CurvePool's own
    /// initialize() revert and permanently bricking every launch that reuses that address.
    function deploy(
        string calldata name,
        string calldata symbol,
        uint256 supply,
        address factory,
        LaunchToken.GuardConfig calldata g,
        bytes32 salt
    ) external returns (address) {
        // Bind the CREATE2 salt to the CALLER so the token's address depends on who deploys it. This deployer is
        // public and stateless (reused across factories), so without this an attacker could call deploy() directly
        // with the victim's exact salt+args and occupy the target address first, bricking the launch. Folding
        // msg.sender into the salt makes an attacker's address differ from the factory's — the collision is gone.
        bytes32 s = keccak256(abi.encodePacked(msg.sender, salt));
        return address(new LaunchToken{salt: s}(name, symbol, supply, factory, g));
    }
}

contract CurvePoolDeployer {
    function deploy(
        address token,
        address weth,
        address v3Factory,
        address platform,
        address dev,
        address bondDeployer,
        address feeConfig,
        uint256 curveSupply,
        uint256 ambushSupply,
        int24 startTick,
        int24 curveWidth,
        int24 minGradWidth
    ) external returns (address) {
        return address(
            new CurvePool(
                token, weth, v3Factory, platform, dev, bondDeployer, feeConfig, curveSupply, ambushSupply, startTick, curveWidth, minGradWidth
            )
        );
    }
}

contract OtcVaultDeployer {
    function deploy(
        address v3Factory,
        address token,
        address weth,
        address sheriff,
        address platform,
        uint32 twapWindow,
        uint256 otcPrice,
        uint256 burnRatio
    ) external returns (address) {
        return address(new OtcVault(v3Factory, token, weth, sheriff, platform, twapWindow, otcPrice, burnRatio));
    }
}

contracts/Disperse.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

/// @title Disperse
/// @notice Send native ETH or an ERC20 to many recipients in a single transaction.
///
/// Non-custodial by design: the contract stores nothing and holds no balance
/// between calls. It has no owner, no upgrade path, no admin — there is nothing
/// to pause, drain, or rug. Every call fans a caller's own funds out to the
/// caller's own list, all-or-nothing (any failed leg reverts the whole tx).
///
/// - `disperseTokenDirect` is the primary path: it moves tokens straight from the
///   sender to each recipient via `transferFrom`, so funds NEVER touch this
///   contract. Safe for fee-on-transfer tokens and the cheapest to reason about.
/// - `disperseToken` pulls the sum once then pays each recipient (one extra hop);
///   kept for callers who prefer a single incoming transfer. NOT for
///   fee-on-transfer tokens (the contract would receive less than the sum).
/// - `disperseEther` fans out `msg.value`; any excess over the summed amounts is
///   refunded to the sender in the same tx.
///
/// Token paths require the sender to `approve` this contract for the summed
/// amount first (standard ERC20 allowance).
contract Disperse is ReentrancyGuard {
    using SafeERC20 for IERC20;

    /// A sane upper bound so a single call can't be built to run out of gas in a
    /// way that wastes a signature; callers batch larger lists across txs.
    uint256 public constant MAX_RECIPIENTS = 600;

    error LengthMismatch();
    error EmptyList();
    error TooManyRecipients();
    error ValueMismatch(); // msg.value < sum(values)
    error EthTransferFailed();

    /// @notice Send `values[i]` of native ETH to `recipients[i]`. Sum(values) must
    /// be <= msg.value; any remainder is refunded to msg.sender.
    function disperseEther(address[] calldata recipients, uint256[] calldata values)
        external
        payable
        nonReentrant
    {
        uint256 n = recipients.length;
        if (n != values.length) revert LengthMismatch();
        if (n == 0) revert EmptyList();
        if (n > MAX_RECIPIENTS) revert TooManyRecipients();

        uint256 total;
        for (uint256 i; i < n; ++i) total += values[i];
        if (msg.value < total) revert ValueMismatch();

        for (uint256 i; i < n; ++i) {
            (bool ok, ) = recipients[i].call{value: values[i]}("");
            if (!ok) revert EthTransferFailed();
        }

        uint256 refund = msg.value - total;
        if (refund > 0) {
            (bool ok, ) = msg.sender.call{value: refund}("");
            if (!ok) revert EthTransferFailed();
        }
    }

    /// @notice Move `values[i]` of `token` straight from msg.sender to
    /// `recipients[i]` (funds never touch this contract). Requires an allowance
    /// of sum(values) to this contract. Safe for fee-on-transfer tokens.
    function disperseTokenDirect(IERC20 token, address[] calldata recipients, uint256[] calldata values)
        external
        nonReentrant
    {
        uint256 n = recipients.length;
        if (n != values.length) revert LengthMismatch();
        if (n == 0) revert EmptyList();
        if (n > MAX_RECIPIENTS) revert TooManyRecipients();

        for (uint256 i; i < n; ++i) {
            token.safeTransferFrom(msg.sender, recipients[i], values[i]);
        }
    }

    /// @notice Pull sum(values) of `token` from msg.sender once, then pay each
    /// recipient. NOT for fee-on-transfer tokens. Requires an allowance of
    /// sum(values) to this contract.
    function disperseToken(IERC20 token, address[] calldata recipients, uint256[] calldata values)
        external
        nonReentrant
    {
        uint256 n = recipients.length;
        if (n != values.length) revert LengthMismatch();
        if (n == 0) revert EmptyList();
        if (n > MAX_RECIPIENTS) revert TooManyRecipients();

        uint256 total;
        for (uint256 i; i < n; ++i) total += values[i];
        token.safeTransferFrom(msg.sender, address(this), total);
        for (uint256 i; i < n; ++i) {
            token.safeTransfer(recipients[i], values[i]);
        }
    }
}

