// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

/// @notice Minimal Uniswap v3 surface the launchpad uses. We intentionally depend on the
/// core factory + pool ONLY (no NonfungiblePositionManager / SwapRouter), because on
/// Robinhood Chain no canonical periphery exists for the verified factory. All liquidity
/// and swaps go through the pool directly via the callbacks below.

interface IUniswapV3Factory {
    function getPool(address tokenA, address tokenB, uint24 fee) external view returns (address pool);
    function createPool(address tokenA, address tokenB, uint24 fee) external returns (address pool);
    function feeAmountTickSpacing(uint24 fee) external view returns (int24);
}

interface IUniswapV3Pool {
    function initialize(uint160 sqrtPriceX96) external;

    function mint(
        address recipient,
        int24 tickLower,
        int24 tickUpper,
        uint128 amount,
        bytes calldata data
    ) external returns (uint256 amount0, uint256 amount1);

    function collect(
        address recipient,
        int24 tickLower,
        int24 tickUpper,
        uint128 amount0Requested,
        uint128 amount1Requested
    ) external returns (uint128 amount0, uint128 amount1);

    function burn(int24 tickLower, int24 tickUpper, uint128 amount)
        external
        returns (uint256 amount0, uint256 amount1);

    function swap(
        address recipient,
        bool zeroForOne,
        int256 amountSpecified,
        uint160 sqrtPriceLimitX96,
        bytes calldata data
    ) external returns (int256 amount0, int256 amount1);

    function increaseObservationCardinalityNext(uint16 observationCardinalityNext) external;

    function observe(uint32[] calldata secondsAgos)
        external
        view
        returns (int56[] memory tickCumulatives, uint160[] memory secondsPerLiquidityCumulativeX128s);

    function observations(uint256 index)
        external
        view
        returns (uint32 blockTimestamp, int56 tickCumulative, uint160 secondsPerLiquidityCumulativeX128, bool initialized);

    function slot0()
        external
        view
        returns (
            uint160 sqrtPriceX96,
            int24 tick,
            uint16 observationIndex,
            uint16 observationCardinality,
            uint16 observationCardinalityNext,
            uint8 feeProtocol,
            bool unlocked
        );

    function liquidity() external view returns (uint128);
    function token0() external view returns (address);
    function token1() external view returns (address);
    function fee() external view returns (uint24);
    function tickSpacing() external view returns (int24);
}

interface IUniswapV3MintCallback {
    function uniswapV3MintCallback(uint256 amount0Owed, uint256 amount1Owed, bytes calldata data) external;
}

interface IUniswapV3SwapCallback {
    function uniswapV3SwapCallback(int256 amount0Delta, int256 amount1Delta, bytes calldata data) external;
}

interface IWETH9 {
    function deposit() external payable;
    function withdraw(uint256) external;
    function transfer(address to, uint256 value) external returns (bool);
    function approve(address spender, uint256 value) external returns (bool);
    function balanceOf(address) external view returns (uint256);
}

contracts/LaunchToken.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import {ERC20} from "@openzeppelin/contracts/token/ERC20/ERC20.sol";

/// @title LaunchToken
/// @notice A clean, hookless meme ERC20 with an AUTO-EXPIRING, BUY-SIDE-ONLY, revert-based
/// anti-snipe guard. There is deliberately NO transfer tax (Uniswap v3 forbids fee-on-transfer),
/// NO mint (supply is fixed at construction), NO blacklist power over sells, NO pausable transfers,
/// and NO owner switch to extend the guard. After the window the token is a permanently normal ERC20.
/// @dev All timing uses block.timestamp: on Arbitrum Orbit, block.number tracks the parent L1 block.
contract LaunchToken is ERC20 {
    struct GuardConfig {
        uint32 deadSecs; // buys revert entirely during this initial window
        uint32 phase1Secs; // tighter caps until launchTime + phase1Secs
        uint32 antiSnipeSecs; // guard fully expires at launchTime + antiSnipeSecs
        uint16 maxTxBps1; // phase 1 max buy size (bps of supply)
        uint16 maxWalletBps1; // phase 1 max wallet (bps of supply)
        uint16 maxTxBps2; // phase 2 max buy size
        uint16 maxWalletBps2; // phase 2 max wallet
        uint32 cooldownSecs; // per-wallet buy cooldown during phase 1
    }

    address public immutable factory;

    // Guard config (immutable — frozen at deploy, cannot be weaponized)
    uint32 public immutable deadSecs;
    uint32 public immutable phase1Secs;
    uint32 public immutable antiSnipeSecs;
    uint16 public immutable maxTxBps1;
    uint16 public immutable maxWalletBps1;
    uint16 public immutable maxTxBps2;
    uint16 public immutable maxWalletBps2;
    uint32 public immutable cooldownSecs;

    bool public tradingEnabled;
    address public pool;
    address public curve; // the CurvePool; may exempt the Bond it deploys at graduation
    uint64 public launchTime;

    mapping(address => bool) public isExempt; // factory, pool, vault — holders/routers, not snipers
    mapping(address => bool) public blocklist; // add-only, buy-side only, frozen after the window
    mapping(address => uint256) public lastBuy;

    error NotFactory();
    error TradingNotLive();
    error AlreadyEnabled();
    error DeadWindow();
    error Blocked();
    error MaxTx();
    error MaxWallet();
    error Cooldown();
    error WindowOver();

    event TradingEnabled(address indexed pool, uint64 launchTime);
    event Blocklisted(address indexed account);

    modifier onlyFactory() {
        if (msg.sender != factory) revert NotFactory();
        _;
    }

    constructor(
        string memory name_,
        string memory symbol_,
        uint256 supply_,
        address factory_,
        GuardConfig memory g
    ) ERC20(name_, symbol_) {
        require(factory_ != address(0), "factory=0");
        require(g.antiSnipeSecs >= g.phase1Secs && g.phase1Secs >= g.deadSecs, "bad windows");
        factory = factory_;
        deadSecs = g.deadSecs;
        phase1Secs = g.phase1Secs;
        antiSnipeSecs = g.antiSnipeSecs;
        maxTxBps1 = g.maxTxBps1;
        maxWalletBps1 = g.maxWalletBps1;
        maxTxBps2 = g.maxTxBps2;
        maxWalletBps2 = g.maxWalletBps2;
        cooldownSecs = g.cooldownSecs;
        isExempt[factory_] = true;
        _mint(factory_, supply_);
    }

    /// @notice Factory-only: record the CurvePool so it can exempt the Bond it deploys at graduation. One-way.
    function setCurve(address curve_) external onlyFactory {
        require(curve == address(0), "curve set");
        require(curve_ != address(0), "curve=0");
        curve = curve_;
    }

    /// @notice Mark an infrastructure address as guard-exempt, so protocol-internal token moves don't trip
    /// maxTx/maxWallet/deadWindow during the anti-snipe window. Callable by the trusted factory (e.g. the
    /// PadRouter, which receives tokens on burnDev/flushBurn buys) and by the CurvePool (the Bond it posts at
    /// graduation — Bond.poke()'s pool.collect() moves the Ambush reserve back to the Bond, which reads as a
    /// "buy" and would otherwise trip the cap when a coin graduates inside the window). Never used for user wallets.
    function exemptAddress(address a) external {
        if (msg.sender != factory && msg.sender != curve) revert NotFactory();
        if (a != address(0)) isExempt[a] = true;
    }

    /// @notice Latches trading on and records the pool + exemptions. Called once, atomically, by the
    /// factory at the end of launch(). One-way — there is no disableTrading().
    function enableTrading(address pool_, address vault_, uint64 launchTime_) external onlyFactory {
        if (tradingEnabled) revert AlreadyEnabled();
        require(pool_ != address(0), "pool=0");
        pool = pool_;
        isExempt[pool_] = true;
        if (vault_ != address(0)) isExempt[vault_] = true;
        launchTime = launchTime_;
        tradingEnabled = true;
        emit TradingEnabled(pool_, launchTime_);
    }

    /// @notice Add known sniper bots to the buy-side blocklist. Add-only, and permanently frozen
    /// once the anti-snipe window ends — it can never be used to block a normal holder's sell.
    function seedBlocklist(address[] calldata bots) external onlyFactory {
        if (tradingEnabled && block.timestamp >= uint256(launchTime) + antiSnipeSecs) revert WindowOver();
        for (uint256 i; i < bots.length; ++i) {
            blocklist[bots[i]] = true;
            emit Blocklisted(bots[i]);
        }
    }

    // ----- live view of the guard (for the UI / DexScreener / honeypot scanners) -----
    function antiSnipeActive() public view returns (bool) {
        return tradingEnabled && block.timestamp < uint256(launchTime) + antiSnipeSecs;
    }

    function windowEndsAt() external view returns (uint256) {
        return uint256(launchTime) + antiSnipeSecs;
    }

    function maxTxNow() public view returns (uint256) {
        if (!antiSnipeActive()) return type(uint256).max;
        uint16 bps = block.timestamp < uint256(launchTime) + phase1Secs ? maxTxBps1 : maxTxBps2;
        return (totalSupply() * bps) / 10_000;
    }

    function maxWalletNow() public view returns (uint256) {
        if (!antiSnipeActive()) return type(uint256).max;
        uint16 bps = block.timestamp < uint256(launchTime) + phase1Secs ? maxWalletBps1 : maxWalletBps2;
        return (totalSupply() * bps) / 10_000;
    }

    function cooldownNow() public view returns (uint256) {
        if (!antiSnipeActive()) return 0;
        return block.timestamp < uint256(launchTime) + phase1Secs ? cooldownSecs : 0;
    }

    function _update(address from, address to, uint256 value) internal override {
        // mint / burn always pass (only the constructor mint and any user burns to 0)
        if (from == address(0) || to == address(0)) {
            super._update(from, to, value);
            return;
        }

        bool fromExempt = isExempt[from];
        bool toExempt = isExempt[to];

        if (!tradingEnabled) {
            // Pre-trading, only the launch flow (factory as an exempt party) may move tokens.
            if (!fromExempt && !toExempt) revert TradingNotLive();
            super._update(from, to, value);
            return;
        }

        // Only enforce guardrails inside the finite window; afterwards this is a one-SLOAD short-circuit.
        if (block.timestamp < uint256(launchTime) + antiSnipeSecs) {
            bool isBuy = (from == pool);
            if (isBuy && !toExempt) {
                if (block.timestamp < uint256(launchTime) + deadSecs) revert DeadWindow();
                if (blocklist[to]) revert Blocked();
                if (value > maxTxNow()) revert MaxTx();
                if (balanceOf(to) + value > maxWalletNow()) revert MaxWallet();
                uint256 cd = cooldownNow();
                if (cd != 0) {
                    if (block.timestamp <= lastBuy[to] + cd) revert Cooldown();
                    lastBuy[to] = block.timestamp;
                }
            }
            // Sells (to == pool) and ordinary wallet transfers are never restricted (anti-honeypot).
        }

        super._update(from, to, value);
    }
}

contracts/libraries/PoolMath.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import {Math} from "@openzeppelin/contracts/utils/math/Math.sol";

/// @title PoolMath
/// @notice Just enough Uniswap v3 math for the launchpad, built ONLY on OZ Math (mulDiv/sqrt).
/// We deliberately avoid TickMath/FullMath: milestone triggers use tick-offset arithmetic and
/// `launchTick` is read straight from slot0, so we never convert tick<->price on-chain.
library PoolMath {
    uint256 internal constant Q96 = 0x1000000000000000000000000; // 2**96
    uint256 internal constant Q192 = 0x1000000000000000000000000000000000000000000000000; // 2**192

    // Full-range position bounds (MIN/MAX tick snapped to tickSpacing 200) and their sqrt ratios,
    // precomputed off-chain (verified) so no TickMath is needed.
    int24 internal constant MIN_TICK = -887200;
    int24 internal constant MAX_TICK = 887200;
    // Exact Uniswap TickMath.getSqrtRatioAtTick(±887200) — must match what a real pool uses.
    uint160 internal constant SQRT_RATIO_AT_MIN_TICK = 4310618292;
    uint160 internal constant SQRT_RATIO_AT_MAX_TICK = 1456195216270955103206513029158776779468408838535;

    // Absolute pool bounds (for unbounded swaps, we clamp just inside these).
    uint160 internal constant MIN_SQRT_RATIO = 4295128739;
    uint160 internal constant MAX_SQRT_RATIO = 1461446703485210103287273052203988822378723970342;

    /// @notice sqrtPriceX96 = sqrt(amount1 / amount0) * 2**96, derived from the seed deposit ratio.
    /// @dev 512-bit safe via mulDiv; result must fit in uint160.
    function sqrtPriceX96FromAmounts(uint256 amount0, uint256 amount1) internal pure returns (uint160) {
        require(amount0 > 0 && amount1 > 0, "amounts=0");
        uint256 ratioX192 = Math.mulDiv(amount1, Q192, amount0);
        uint256 sqrtP = Math.sqrt(ratioX192);
        require(sqrtP <= type(uint160).max, "sqrtP overflow");
        // Bound to the full-range POSITION's tick-snapped sqrt ratios (not the absolute pool bounds),
        // so fullRangeLiquidity's (sqrtB - sqrtP) / (sqrtP - sqrtA) can never underflow.
        require(sqrtP > SQRT_RATIO_AT_MIN_TICK && sqrtP < SQRT_RATIO_AT_MAX_TICK, "price out of range");
        return uint160(sqrtP);
    }

    /// @notice Liquidity for a full-range position given the current price and both amounts.
    /// Standard Uniswap LiquidityAmounts.getLiquidityForAmounts specialized to the full range;
    /// returns min(L0, L1) so neither owed amount can exceed what we hold.
    function fullRangeLiquidity(uint160 sqrtP, uint256 amount0, uint256 amount1)
        internal
        pure
        returns (uint128 liquidity)
    {
        uint160 sqrtA = SQRT_RATIO_AT_MIN_TICK;
        uint160 sqrtB = SQRT_RATIO_AT_MAX_TICK;
        // sqrtP is guaranteed strictly between sqrtA and sqrtB for any launch price.
        uint256 l0 = _liquidityForAmount0(sqrtP, sqrtB, amount0);
        uint256 l1 = _liquidityForAmount1(sqrtA, sqrtP, amount1);
        uint256 l = l0 < l1 ? l0 : l1;
        require(l > 0 && l <= type(uint128).max, "bad liquidity");
        liquidity = uint128(l);
    }

    /// @notice Like fullRangeLiquidity but returns 0 instead of reverting when the fees are one-sided or too
    /// small to mint any liquidity. Lets the Bond compound Sherwood fees back in and skip gracefully on dust.
    function fullRangeLiquidityOrZero(uint160 sqrtP, uint256 amount0, uint256 amount1)
        internal
        pure
        returns (uint128)
    {
        if (amount0 == 0 || amount1 == 0) return 0;
        // Honor the "return 0, never revert" contract at price extremes: if spot is at/below the position's lower
        // bound or at/above its upper, one of the sub-computations would underflow (sqrtP - SQRT_RATIO_AT_MIN_TICK)
        // or divide by zero (SQRT_RATIO_AT_MAX_TICK - sqrtP). Skip gracefully instead of reverting (which would
        // brick Bond.poke on a token pinned to a price extreme).
        if (sqrtP <= SQRT_RATIO_AT_MIN_TICK || sqrtP >= SQRT_RATIO_AT_MAX_TICK) return 0;
        uint256 l0 = _liquidityForAmount0(sqrtP, SQRT_RATIO_AT_MAX_TICK, amount0);
        uint256 l1 = _liquidityForAmount1(SQRT_RATIO_AT_MIN_TICK, sqrtP, amount1);
        uint256 l = l0 < l1 ? l0 : l1;
        if (l == 0 || l > type(uint128).max) return 0;
        return uint128(l);
    }

    function _liquidityForAmount0(uint160 sqrtLower, uint160 sqrtUpper, uint256 amount0)
        private
        pure
        returns (uint256)
    {
        // L = amount0 * (sqrtLower * sqrtUpper / Q96) / (sqrtUpper - sqrtLower)
        uint256 intermediate = Math.mulDiv(uint256(sqrtLower), uint256(sqrtUpper), Q96);
        return Math.mulDiv(amount0, intermediate, uint256(sqrtUpper) - uint256(sqrtLower));
    }

    function _liquidityForAmount1(uint160 sqrtLower, uint160 sqrtUpper, uint256 amount1)
        private
        pure
        returns (uint256)
    {
        // L = amount1 * Q96 / (sqrtUpper - sqrtLower)
        return Math.mulDiv(amount1, Q96, uint256(sqrtUpper) - uint256(sqrtLower));
    }

    /// @notice Liquidity for an in-range position at ARBITRARY bounds [sqrtA,sqrtB] given the current price
    /// sqrtP and both amounts. Canonical Uniswap LiquidityAmounts.getLiquidityForAmounts (in-range branch),
    /// returning min(L0,L1) so neither owed amount can exceed what we hold. Returns 0 on dust/one-sided.
    /// Used for full-range mints whose tick bounds depend on the pool's tickSpacing (not the hardcoded ±887200).
    function getLiquidityForAmounts(uint160 sqrtP, uint160 sqrtA, uint160 sqrtB, uint256 amount0, uint256 amount1)
        internal
        pure
        returns (uint128)
    {
        if (sqrtA > sqrtB) (sqrtA, sqrtB) = (sqrtB, sqrtA);
        if (amount0 == 0 || amount1 == 0 || sqrtP <= sqrtA || sqrtP >= sqrtB) return 0;
        uint256 l0 = _liquidityForAmount0(sqrtP, sqrtB, amount0);
        uint256 l1 = _liquidityForAmount1(sqrtA, sqrtP, amount1);
        uint256 l = l0 < l1 ? l0 : l1;
        if (l == 0 || l > type(uint128).max) return 0;
        return uint128(l);
    }

    /// @notice Liquidity for a SINGLE-SIDED (range-order) position that sits entirely on one side of the
    /// current price. `token0Side` = the band is entirely ABOVE the current tick (holds only token0);
    /// otherwise it is entirely BELOW (holds only token1). `sqrtLo`/`sqrtHi` are the band's tick bounds.
    function singleSidedLiquidity(uint160 sqrtLo, uint160 sqrtHi, uint256 amount, bool token0Side)
        internal
        pure
        returns (uint128)
    {
        require(sqrtHi > sqrtLo, "band");
        uint256 l = token0Side
            ? _liquidityForAmount0(sqrtLo, sqrtHi, amount)
            : _liquidityForAmount1(sqrtLo, sqrtHi, amount);
        require(l > 0 && l <= type(uint128).max, "bad L");
        return uint128(l);
    }

    /// @notice Like singleSidedLiquidity but returns 0 instead of reverting when the band is empty or the
    /// amount is too small to make any liquidity. Lets a caller (the Bond) skip a placement gracefully.
    function singleSidedLiquidityOrZero(uint160 sqrtLo, uint160 sqrtHi, uint256 amount, bool token0Side)
        internal
        pure
        returns (uint128)
    {
        if (amount == 0 || sqrtHi <= sqrtLo) return 0;
        uint256 l = token0Side ? _liquidityForAmount0(sqrtLo, sqrtHi, amount) : _liquidityForAmount1(sqrtLo, sqrtHi, amount);
        if (l == 0 || l > type(uint128).max) return 0;
        return uint128(l);
    }

    /// @notice Canonical Uniswap v3 TickMath.getSqrtRatioAtTick — sqrt(1.0001^tick) * 2^96.
    /// Used to price the TWAP mean tick for manipulation-resistant slippage floors (relies on unchecked
    /// overflow exactly as Uniswap's original does).
    function getSqrtRatioAtTick(int24 tick) internal pure returns (uint160 sqrtPriceX96) {
        unchecked {
            uint256 absTick = tick < 0 ? uint256(-int256(tick)) : uint256(int256(tick));
            require(absTick <= 887272, "T");
            uint256 ratio =
                absTick & 0x1 != 0 ? 0xfffcb933bd6fad37aa2d162d1a594001 : 0x100000000000000000000000000000000;
            if (absTick & 0x2 != 0) ratio = (ratio * 0xfff97272373d413259a46990580e213a) >> 128;
            if (absTick & 0x4 != 0) ratio = (ratio * 0xfff2e50f5f656932ef12357cf3c7fdcc) >> 128;
            if (absTick & 0x8 != 0) ratio = (ratio * 0xffe5caca7e10e4e61c3624eaa0941cd0) >> 128;
            if (absTick & 0x10 != 0) ratio = (ratio * 0xffcb9843d60f6159c9db58835c926644) >> 128;
            if (absTick & 0x20 != 0) ratio = (ratio * 0xff973b41fa98c081472e6896dfb254c0) >> 128;
            if (absTick & 0x40 != 0) ratio = (ratio * 0xff2ea16466c96a3843ec78b326b52861) >> 128;
            if (absTick & 0x80 != 0) ratio = (ratio * 0xfe5dee046a99a2a811c461f1969c3053) >> 128;
            if (absTick & 0x100 != 0) ratio = (ratio * 0xfcbe86c7900a88aedcffc83b479aa3a4) >> 128;
            if (absTick & 0x200 != 0) ratio = (ratio * 0xf987a7253ac413176f2b074cf7815e54) >> 128;
            if (absTick & 0x400 != 0) ratio = (ratio * 0xf3392b0822b70005940c7a398e4b70f3) >> 128;
            if (absTick & 0x800 != 0) ratio = (ratio * 0xe7159475a2c29b7443b29c7fa6e889d9) >> 128;
            if (absTick & 0x1000 != 0) ratio = (ratio * 0xd097f3bdfd2022b8845ad8f792aa5825) >> 128;
            if (absTick & 0x2000 != 0) ratio = (ratio * 0xa9f746462d870fdf8a65dc1f90e061e5) >> 128;
            if (absTick & 0x4000 != 0) ratio = (ratio * 0x70d869a156d2a1b890bb3df62baf32f7) >> 128;
            if (absTick & 0x8000 != 0) ratio = (ratio * 0x31be135f97d08fd981231505542fcfa6) >> 128;
            if (absTick & 0x10000 != 0) ratio = (ratio * 0x9aa508b5b7a84e1c677de54f3e99bc9) >> 128;
            if (absTick & 0x20000 != 0) ratio = (ratio * 0x5d6af8dedb81196699c329225ee604) >> 128;
            if (absTick & 0x40000 != 0) ratio = (ratio * 0x2216e584f5fa1ea926041bedfe98) >> 128;
            if (absTick & 0x80000 != 0) ratio = (ratio * 0x48a170391f7dc42444e8fa2) >> 128;
            if (tick > 0) ratio = type(uint256).max / ratio;
            sqrtPriceX96 = uint160((ratio >> 32) + (ratio % (1 << 32) == 0 ? 0 : 1));
        }
    }

    /// @notice WETH-per-token (1e18-scaled) at a TWAP mean tick — manipulation-resistant (unlike spot).
    function twapPriceWethPerToken(int24 tick, bool tokenIsToken0) internal pure returns (uint256) {
        return quoteWethPerToken(getSqrtRatioAtTick(tick), tokenIsToken0);
    }

    // ── forward amount math (canonical Uniswap LiquidityAmounts) — value a position for NAV ──
    function getAmount0ForLiquidity(uint160 sqrtA, uint160 sqrtB, uint128 liquidity) internal pure returns (uint256) {
        if (sqrtA > sqrtB) (sqrtA, sqrtB) = (sqrtB, sqrtA);
        return Math.mulDiv(uint256(liquidity) << 96, uint256(sqrtB) - uint256(sqrtA), uint256(sqrtB)) / uint256(sqrtA);
    }

    function getAmount1ForLiquidity(uint160 sqrtA, uint160 sqrtB, uint128 liquidity) internal pure returns (uint256) {
        if (sqrtA > sqrtB) (sqrtA, sqrtB) = (sqrtB, sqrtA);
        return Math.mulDiv(uint256(liquidity), uint256(sqrtB) - uint256(sqrtA), Q96);
    }

    /// @notice Token amounts a `liquidity` position at [sqrtA,sqrtB] holds at price `sqrtP` — canonical
    /// Uniswap v3 getAmountsForLiquidity. Used to value a vault position (NAV), never for a gate.
    function getAmountsForLiquidity(uint160 sqrtP, uint160 sqrtA, uint160 sqrtB, uint128 liquidity)
        internal
        pure
        returns (uint256 amount0, uint256 amount1)
    {
        if (sqrtA > sqrtB) (sqrtA, sqrtB) = (sqrtB, sqrtA);
        if (sqrtP <= sqrtA) {
            amount0 = getAmount0ForLiquidity(sqrtA, sqrtB, liquidity);
        } else if (sqrtP < sqrtB) {
            amount0 = getAmount0ForLiquidity(sqrtP, sqrtB, liquidity);
            amount1 = getAmount1ForLiquidity(sqrtA, sqrtP, liquidity);
        } else {
            amount1 = getAmount1ForLiquidity(sqrtA, sqrtB, liquidity);
        }
    }

    /// @notice Arithmetic-mean tick over `window` seconds from the pool's oracle cumulatives.
    function meanTick(int56 tickCumulativeStart, int56 tickCumulativeEnd, uint32 window)
        internal
        pure
        returns (int24)
    {
        int56 delta = tickCumulativeEnd - tickCumulativeStart;
        int56 avg = delta / int56(uint56(window));
        // Round toward negative infinity (matches Uniswap OracleLibrary) for exactness.
        if (delta < 0 && (delta % int56(uint56(window)) != 0)) avg--;
        return int24(avg);
    }

    /// @notice price(WETH per token, scaled by 1e18) implied by a sqrtPriceX96, respecting ordering.
    /// Only used for slippage/min-out estimates, never for the milestone gate.
    /// @dev Never squares the full sqrtPrice directly (that overflows uint256 for large sqrtPrice);
    /// the intermediate is divided by Q96 first so mulDiv stays in range.
    function quoteWethPerToken(uint160 sqrtPriceX96, bool tokenIsToken0) internal pure returns (uint256) {
        uint256 s = uint256(sqrtPriceX96);
        if (tokenIsToken0) {
            // WETH per token = (sqrtP/2^96)^2, scaled by 1e18
            uint256 p = Math.mulDiv(s, s, Q96); // = price * 2^96, no overflow
            return Math.mulDiv(p, 1e18, Q96);
        } else {
            // token is token1: WETH per token = (2^96/sqrtP)^2 = 2^192 / sqrtP^2, scaled by 1e18
            uint256 a = Math.mulDiv(Q96, 1e18, s);
            return Math.mulDiv(a, Q96, s);
        }
    }
}

contracts/OtcVault.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import {Math} from "@openzeppelin/contracts/utils/math/Math.sol";
import {IUniswapV3Factory, IUniswapV3Pool} from "./interfaces/IUniswapV3.sol";
import {PoolMath} from "./libraries/PoolMath.sol";

/// @title OtcVault
/// @notice Per-launch OTC desk holding 20% of supply. After the token graduates and its TWAP market cap
/// reaches the OTC level (~$10k), the window opens: buyers **burn $SHERIFF** to unlock an allocation
/// (bigger burn → bigger per-wallet cap) and buy the token at the fixed OTC price — no matter how high the
/// market has run. The ETH they pay goes straight to the platform wallet. Burning $SHERIFF is a permanent
/// supply sink that benefits every $SHERIFF holder.
contract OtcVault is ReentrancyGuard {
    using SafeERC20 for IERC20;

    address public constant BURN = 0x000000000000000000000000000000000000dEaD;
    uint24 public constant POOL_FEE = 10000;

    IUniswapV3Factory public immutable v3Factory;
    IERC20 public immutable token; // the launched token (this vault holds 20% of it)
    address public immutable weth;
    IERC20 public immutable sheriff; // burned for access
    address public immutable platform; // receives the OTC ETH
    bool public immutable tokenIsToken0;
    uint32 public immutable twapWindow;
    uint256 public immutable otcPrice; // WETH-wei per 1e18 token — the fixed "$10k-MC" price + open trigger
    uint256 public immutable burnRatio; // project tokens unlocked per 1 $SHERIFF burned

    bool public active;
    IUniswapV3Pool public pool;
    uint256 public totalSold;
    mapping(address => uint256) public burned; // $SHERIFF a wallet has burned (cumulative)
    mapping(address => uint256) public purchased; // tokens a wallet has bought (cumulative)

    error NotActive();
    error AlreadyActive();
    error NoPool();
    error NotOpen();
    error OverAllowance();
    error SoldOut();
    error Underpaid();

    event Activated(address indexed pool);
    event OtcBuy(address indexed buyer, uint256 sheriffBurned, uint256 tokensOut, uint256 ethPaid);

    constructor(
        address v3Factory_,
        address token_,
        address weth_,
        address sheriff_,
        address platform_,
        uint32 twapWindow_,
        uint256 otcPrice_,
        uint256 burnRatio_
    ) {
        require(
            v3Factory_ != address(0) && token_ != address(0) && weth_ != address(0) && sheriff_ != address(0)
                && platform_ != address(0),
            "zero"
        );
        require(twapWindow_ >= 600 && otcPrice_ > 0 && burnRatio_ > 0, "params");
        v3Factory = IUniswapV3Factory(v3Factory_);
        token = IERC20(token_);
        weth = weth_;
        sheriff = IERC20(sheriff_);
        platform = platform_;
        twapWindow = twapWindow_;
        otcPrice = otcPrice_;
        burnRatio = burnRatio_;
        tokenIsToken0 = token_ < weth_;
    }

    /// @notice Bind the graduated pool (permissionless; validates the canonical initialized pool).
    function activate() external {
        if (active) revert AlreadyActive();
        address p = v3Factory.getPool(address(token), weth, POOL_FEE);
        if (p == address(0)) revert NoPool();
        (uint160 sqrtP,,,,,,) = IUniswapV3Pool(p).slot0();
        if (sqrtP == 0) revert NoPool();
        pool = IUniswapV3Pool(p);
        active = true;
        emit Activated(p);
    }

    /// @notice Is the OTC open? Opens once the 30-min TWAP price reaches the OTC price (~$10k MC).
    function isOpen() public view returns (bool) {
        if (!active) return false;
        return PoolMath.twapPriceWethPerToken(_meanTick(), tokenIsToken0) >= otcPrice;
    }

    /// @notice Tokens `wallet` may still buy, given what it has burned and bought.
    function allowanceOf(address wallet) public view returns (uint256) {
        uint256 unlocked = burned[wallet] * burnRatio / 1e18;
        return unlocked > purchased[wallet] ? unlocked - purchased[wallet] : 0;
    }

    /// @notice Burn `sheriffBurn` $SHERIFF (0 to reuse prior burn) and buy `tokenAmount` at the OTC price.
    function buyOtc(uint256 sheriffBurn, uint256 tokenAmount) external payable nonReentrant {
        if (!active) revert NotActive();
        if (!isOpen()) revert NotOpen();
        if (tokenAmount == 0) revert SoldOut();

        if (sheriffBurn > 0) {
            sheriff.safeTransferFrom(msg.sender, BURN, sheriffBurn);
            burned[msg.sender] += sheriffBurn;
        }
        if (tokenAmount > allowanceOf(msg.sender)) revert OverAllowance();
        if (tokenAmount > token.balanceOf(address(this))) revert SoldOut();

        uint256 cost = Math.mulDiv(tokenAmount, otcPrice, 1e18);
        if (msg.value < cost) revert Underpaid();

        purchased[msg.sender] += tokenAmount;
        totalSold += tokenAmount;

        token.safeTransfer(msg.sender, tokenAmount);
        (bool ok,) = platform.call{value: cost}(""); // OTC ETH -> platform wallet
        require(ok, "eth");
        if (msg.value > cost) {
            (bool r,) = msg.sender.call{value: msg.value - cost}(""); // refund overpay
            require(r, "refund");
        }
        emit OtcBuy(msg.sender, sheriffBurn, tokenAmount, cost);
    }

    function remaining() external view returns (uint256) {
        return token.balanceOf(address(this));
    }

    function _meanTick() internal view returns (int24) {
        uint32[] memory ago = new uint32[](2);
        ago[0] = twapWindow;
        ago[1] = 0;
        (int56[] memory cum,) = pool.observe(ago);
        return PoolMath.meanTick(cum[0], cum[1], twapWindow);
    }
}
